window.ROUTE_JIANGWAN = {"id":"jiangwan","name":"江晚","floor":25,"flag1Week":28,"flag2Week":39,"flag1Need":60,"flag2Need":80,"flag1Label":"天台","flag2Label":"画室","tagline":"「有些颜色，要两个人一起看才算数。」","chapters":[{"id":"extra","title":"番外 · 童年","scenes":[{"no":1,"title":"一墙的雨","week":0,"bg":"corridor_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"雨从早上开始下，下到下午还没停。少年宫三楼的走廊很长，一头是奥数班，一头是美术班。"},{"t":"n","text":"你妈妈把伞收在门口的铁桶里。桶里已经插了七八把，都滴着水，桶底积了一层。"},{"t":"n","text":"走廊的墙上贴满画。太阳、房子、一家人手拉手。四个角用图钉按着，有的角翘起来了，风一过就抖。"},{"t":"n","text":"你在等下课。走廊尽头蹲着一个女孩，膝盖上摊着一张纸，手里捏着一支蜡笔。"},{"t":"n","text":"她不是在纸上画。她在墙上画——就在一幅《我的家》的右下角，画了一小片雨。"},{"t":"n","text":"值班老师从办公室出来，看了一眼，说：「别画墙上。」她说：「知道了。」老师走了，她接着画。"},{"t":"n","text":"你走过去，蹲在她旁边。她画的雨是斜的，一道一道，落得很急。"},{"t":"n","text":"你说：「雨是直的。」"},{"t":"n","text":"她抬头看了你一眼。眼睛很黑，看完就低下去。"},{"t":"c","id":"jiangwan","text":"落下来的时候，风会吹。你看窗外。"},{"t":"n","text":"窗外是直的。可她画的是斜的。"},{"t":"n","text":"她把最后一道画完，收笔，用袖子去擦。擦不掉，反而糊开一小片。"},{"t":"c","id":"jiangwan","text":"擦不掉了。"},{"t":"n","text":"她说这句话的时候不着急，像在报告一件跟自己有关、但不要紧的事。"},{"t":"n","text":"楼下有人喊了一个名字。她应了一声，把蜡笔往窗台上一放，跑了。"},{"t":"n","text":"跑到楼梯口，她回头看了一眼那面墙。不是看你。"},{"t":"n","text":"蜡笔留在窗台上。赭石色，很短，纸皮撕掉了一半，露出里面的芯。"},{"t":"n","text":"美术班的门虚掩着。你走过去，从门缝往里看。"},{"t":"n","text":"十几个孩子围着一张长桌，桌上摆着颜料盘，一格一格，像药盒。有个男孩把蓝色涂到了纸外面。"},{"t":"n","text":"老师在说：「先画轮廓，别急着上色。颜色是最后的事。」"},{"t":"n","text":"最里面靠窗的位置空着，桌上放着一张没画完的画。"},{"t":"n","text":"画的是窗外。梧桐、三楼、晾着的衣服。比走廊上那些都认真。"},{"t":"n","text":"你猜是她的。"},{"t":"n","text":"奥数班的门开了。你妈妈在走廊那头喊你的名字，声音压得很低，怕吵到别人上课。"},{"t":"n","text":"你跑过去。她的手心是暖的，摸了摸你的头，说：「怎么跑到那边去了。」"},{"t":"n","text":"你说，看画。"},{"t":"n","text":"她说：「看画能考上中学吗。」"},{"t":"n","text":"她不是生气。她只是随口一问，问完就去拎你的书包。"},{"t":"n","text":"下楼的时候，走廊里的画在你身后一排一排退过去。太阳、房子、一家人手拉手。"},{"t":"n","text":"回家的路上雨停了。路边的梧桐往下滴水，一滴一滴，砸在水洼里。"},{"t":"n","text":"你把手插在口袋里，摸到那支蜡笔。它还是温的。"},{"t":"n","text":"那天晚上你做了一个梦。梦里有一面很长的墙，墙上的雨全是斜的，一直下到你醒。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把蜡笔放进口袋","hint":"留下一点颜色 · 心情 ↑","eff":{"happy":2.0,"cre":1.0},"reply":[{"t":"n","text":"你把它攥在手心。蜡有点软，被体温捂暖了。"},{"t":"n","text":"回家的路上你一直没松手。晚上洗手，怎么搓，指缝里都还留着一点赭石色。"}]},{"label":"B","text":"追下楼还给她","hint":"跑一趟楼梯 · 情商 ↑","eff":{"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你追到楼下。她坐在自行车后座上，被她妈妈推着往大门走。"},{"t":"n","text":"你举着蜡笔喊了一声。她回头，车已经拐出去了。"},{"t":"n","text":"第二天走廊上的画换了新的。那片雨没有了。"}]},{"label":"C","text":"在她的雨旁边画一把伞","hint":"给雨画把伞 · 创造力 ↑","eff":{"cre":2.0,"happy":1.0,"aff":1.0},"reply":[{"t":"n","text":"你画了一把伞，画得很丑，伞骨歪着，柄也短。"},{"t":"n","text":"值班老师又出来了。她看了两秒，问：「谁画的？」你说你。她叹了口气：「下次画纸上。」"},{"t":"n","text":"那面墙一直留到暑假。伞和雨都在。"}]}]},{"t":"n","text":"楼下喊的那个名字，你听见了，没有记住。你记住的是墙上的雨，是斜的。"},{"t":"n","text":"很多年后你路过那里。社区活动中心门口挂着一块牌子，写着开放时间。"},{"t":"n","text":"三楼的走廊没有了，改成了一间阅览室。墙是新刷的，白的。"},{"t":"n","text":"你在门口站了一会儿，想不起来自己在找什么。"}],"id":"jiangwan_01"},{"no":2,"title":"三块钱的钴蓝","week":0,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"美术用品店开在学校对面，玻璃柜里摆着颜料，柜台上压一张塑料布，边角发黄。"},{"t":"n","text":"你进来买素描纸。八开，二十张，六块。"},{"t":"n","text":"柜台前站着一个女孩，比你矮半个头，扎着马尾，背一个洗得发白的书包。她把硬币一枚一枚排在柜台上。"},{"t":"n","text":"老板娘按着计算器：「钴蓝，十一。」"},{"t":"n","text":"硬币数到八。女孩停了一下，又把手伸进书包侧袋，翻了翻。"},{"t":"n","text":"侧袋是空的。她把硬币拢在一起，说：「八块。」"},{"t":"n","text":"她把书包放上柜台：「这个押这儿，我明天带钱来。」"},{"t":"n","text":"老板娘看了她一眼，没接。"},{"t":"n","text":"你口袋里有三块，是今天的午饭钱。中午你吃了同学半个包子。"},{"t":"n","text":"老板娘四十来岁，头发用一根皮筋盘着，算账很快，算完就把钱扫进抽屉。"},{"t":"n","text":"店里有一股亚麻仁油的味道，混着纸和灰。"},{"t":"n","text":"女孩穿的校服不是你学校的。袖口磨白了，书包的肩带断过，用别针别着。"},{"t":"n","text":"她数钱数得很慢，一枚一枚，数到十一，停住，又从侧袋里摸出几个一角的。"},{"t":"n","text":"柜台上那管钴蓝立着，标签朝外，蓝色的格子印得有点偏。"},{"t":"n","text":"她看了那管蓝一眼，又低头看自己的硬币。"},{"t":"n","text":"老板娘说：「要不你先买别的。」"},{"t":"n","text":"她摇头：「就要这个。」"},{"t":"n","text":"她把书包放到柜台上，动作很轻，像怕把什么东西碰坏。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"替她补上三块，报上名字","hint":"三块钱的事 · 心情 ↑","eff":{"happy":3.0,"eq":2.0,"aff":2.0},"reply":[{"t":"n","text":"你把三块钱放在柜台上。她转过头，看了你很久。"},{"t":"n","text":"老板娘把颜料推过来。她拿在手里，没有立刻收起来。"},{"t":"c","id":"jiangwan","text":"你叫什么。"},{"t":"n","text":"你说了。她从书包里掏出速写本，翻到最后一页，写下一行字：三块，九月十七。"},{"t":"n","text":"写完她把本子合上，说：「我记着。」"}]},{"label":"B","text":"说「我先借你」，让她写下来","hint":"把账记清 · 好感 ↑","eff":{"aff":3.0,"eq":1.0},"reply":[{"t":"n","text":"你说，借你，什么时候还都行。"},{"t":"n","text":"她摇头：「不行。你写个名字。」"},{"t":"n","text":"你把名字写在她的速写本上。她在旁边补了一个日期，又补了一句：「下周三，这儿。」"},{"t":"n","text":"下周三她没来。再下周三也没有。"}]},{"label":"C","text":"什么也没说，把钱放下就走","hint":"不留名字 · 心情 ↑","eff":{"happy":1.0,"cha":1.0},"reply":[{"t":"n","text":"你把钱放在柜台上，转身出门。玻璃门上的铃响了一声。"},{"t":"n","text":"走到街角，你听见后面有人喊。你没回头。"},{"t":"n","text":"你不知道她有没有买到那管蓝。"},{"t":"n","text":"出门的时候天已经暗了。路灯一盏一盏亮起来，先是黄的，再变白。"},{"t":"n","text":"玻璃门上的铃还在响。你走出去很远，还能听见。"},{"t":"n","text":"回家要经过一条小巷，巷子里有一家裁缝店，门口的灯管坏了一根，一闪一闪。"},{"t":"n","text":"你妈妈问你钱怎么少了三块。你说买纸了。"},{"t":"n","text":"她「哦」了一声，说：「下次说一声。」"},{"t":"n","text":"晚上你把素描纸摊在桌上。纸是新的，有点潮，边角翘着。"},{"t":"n","text":"你想起柜台上那管钴蓝。标签上的蓝印得有点偏，像一小块天。"},{"t":"n","text":"十一块钱一管。你一个月的零花钱是二十。"},{"t":"n","text":"这个数字你记了很久。"},{"t":"n","text":"第二天上学，你在书包里翻那张素描纸，翻出一枚一角硬币，不知道什么时候掉进去的。"},{"t":"n","text":"你把它放进铅笔盒，一直没花。"},{"t":"n","text":"那个学期你画了很多张画，画的都是窗户，画得不好。"},{"t":"n","text":"期末，美术老师在你的作业本上写：有想法，但基本功要练。"},{"t":"n","text":"你把那张评语剪下来，夹在字典里。"},{"t":"n","text":"很多年以后，你已经想不起那个女孩的脸。你只记得她数硬币的样子，很认真。"}]}]},{"t":"n","text":"那半管钴蓝后来出现在高中画室的颜料盒里，盖子裂了，用透明胶缠了两圈。"},{"t":"n","text":"她说这个牌子的蓝，现在十四块。她没说那三块钱。"},{"t":"n","text":"她大概不记得你的脸。她记得你的名字——因为名字是写在纸上的。"}],"id":"jiangwan_02"},{"no":3,"title":"割下来的墙","week":0,"bg":"corridor_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"暑假的第二个星期，少年宫门口贴了一张通知：原址改建社区活动中心，八月十日起施工。"},{"t":"n","text":"走廊上的画还在。工人已经开始在楼下搬东西，楼梯间堆着拆下来的木门。"},{"t":"n","text":"你上三楼的时候，她已经在了。"},{"t":"n","text":"她带了一把美工刀，蹲在那面墙前，正在割自己画过的那一块。"},{"t":"n","text":"涂料是后来刷的，白得发亮。刀的尖划开墙面，露出里面灰扑扑的水泥。"},{"t":"c","id":"jiangwan","text":"你来干嘛。"},{"t":"n","text":"你说不知道。你说听说要拆了。"},{"t":"n","text":"她低下头，继续割。刀不快，割得很慢，一条边要来回划好几下。"},{"t":"c","id":"jiangwan","text":"这块是我画的。割下来还能带走。"},{"t":"n","text":"她割的是一块巴掌大的墙皮，带着那片斜的雨。背面的水泥很沉。"},{"t":"n","text":"她从书包里拿出报纸，一层一层包好，包成一个方方正正的小包。"},{"t":"n","text":"楼下有工人在拆旧黑板。锤子敲在木头上，声音很闷。"},{"t":"n","text":"他们把拆下来的东西堆在院子里：黑板、木架、一摞旧报纸、几把没有靠背的椅子。"},{"t":"n","text":"她割完一块，没有马上起来。她用手指摸了摸露出来的水泥。"},{"t":"c","id":"jiangwan","text":"里面是灰的。"},{"t":"n","text":"她说，好像有点意外。"},{"t":"n","text":"你说，墙里面本来就是灰的。"},{"t":"c","id":"jiangwan","text":"我知道。可是我一直以为，里面也是白的。"},{"t":"n","text":"她把刀换了个方向，继续割另一条边。刀不快，割两下就要停一下，甩甩手。"},{"t":"n","text":"你说我来。她没让。"},{"t":"c","id":"jiangwan","text":"我自己割。"},{"t":"n","text":"她割了大概二十分钟。额头上有一层细汗，袖子蹭到了墙灰。"},{"t":"n","text":"割下来的墙皮比她想的沉。她捧着，像捧一块砖。"},{"t":"n","text":"报纸是楼下捡的，上面有招聘启事和房屋出租。"},{"t":"n","text":"她一条一条叠好，把墙皮放进去，四个角折起来，压平。"},{"t":"n","text":"包完，她把包放在地上，站起来，拍了拍手上的灰。"},{"t":"c","id":"jiangwan","text":"行了。"},{"t":"n","text":"她看着那面被割了一块的墙。缺口不大，但在满墙的画里很显眼。"},{"t":"c","id":"jiangwan","text":"反正要刷了。"},{"t":"n","text":"她说这话的时候，语气跟刚才说「里面是灰的」一样。"},{"t":"n","text":"楼下有人喊：小心，别站窗户底下。"},{"t":"n","text":"你们退到走廊中间。工人抬着一扇旧门从楼梯上来，门框上还挂着牌子。"},{"t":"n","text":"她往边上让。让的时候，一只手一直按着地上的报纸包。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"要一块","hint":"收下一角墙 · 好感 ↑","eff":{"aff":4.0,"happy":3.0},"reply":[{"t":"n","text":"你说，能不能也给我一块。"},{"t":"n","text":"她愣了一下，然后把刀递给你。"},{"t":"n","text":"你割得很歪。她看了看，说：「也行。歪的这块比较像我割的。」"},{"t":"n","text":"那一角墙皮你夹在字典里。很多年后翻出来，已经碎成三块。"}]},{"label":"B","text":"帮她割","hint":"一起动手 · 创造力 ↑","eff":{"cre":3.0,"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你蹲下来，帮她按住墙皮。刀走的时候，灰往下掉，落在她的鞋面上。"},{"t":"n","text":"割到一半，刀尖断了。她「啧」了一声，从笔袋里又摸出一片刀片。"},{"t":"n","text":"她说：「你手挺稳的。」这是她第一次夸你。"}]},{"label":"C","text":"说「反正要拆了」","hint":"说句实话 · 心情 ↑","eff":{"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"你说，反正要拆了，留着也没用。"},{"t":"n","text":"她停下手，看了你一会儿。"},{"t":"c","id":"jiangwan","text":"你说得对。"},{"t":"n","text":"但她还是把那块割完了，包好，放进书包。书包鼓起来一块。"}]}]},{"t":"n","text":"下楼的时候，她把刀收进笔袋，拉链拉到底。"},{"t":"c","id":"jiangwan","text":"以后我要有一间自己的墙。整面墙都是我的，我想画什么画什么。"},{"t":"n","text":"她说得很平常，像在说明天要吃什么。"},{"t":"n","text":"八月十号，少年宫开始拆。你路过一次，看见三楼的窗框已经被卸下来了。"},{"t":"n","text":"后来那里起了一栋新楼，五层，米黄色。一楼是社区食堂，中午有很多老人排队。"},{"t":"n","text":"你上大学那年回来过一次。食堂的墙上挂着几幅装饰画，印刷的，画的是向日葵。"},{"t":"n","text":"你站在那面墙前面，想，如果她现在回来，会说什么。"},{"t":"n","text":"她大概会说：「这个黄，太亮了。」"}],"id":"jiangwan_03"},{"no":4,"title":"她的窗户","week":0,"bg":"campus_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"初三的秋天，你妈妈开始每天问你模考排名。她说，考不上就复读，复读一年不丢人。"},{"t":"n","text":"你没说话。你只是把桌上的画收进了柜子，收了两年。"},{"t":"n","text":"那天你去同学家借一本数学资料。他家在城西的老居民楼，六层，水刷石外墙。"},{"t":"n","text":"楼道里堆着蜂窝煤，墙上贴着通下水道的小广告。声控灯要拍两下才亮。"},{"t":"n","text":"同学的妈妈留你吃饭。一盘炒青菜，一碗蛋汤。她说：「多吃点，读书费脑子。」"},{"t":"n","text":"从他家出来已经九点。你手里拎着那本资料，书角硌着手心。"},{"t":"n","text":"你抄近路，穿过一排梧桐。叶子落了一半，路灯从枝叶里漏下来，地上一块一块的光。"},{"t":"n","text":"三楼有一扇窗亮着，比别的窗都亮。"},{"t":"n","text":"窗里有个女孩，坐在桌前画画。"},{"t":"n","text":"她面前支着一块板，板上是画布。桌上摊着颜料管，一管一管按颜色排开。"},{"t":"n","text":"窗台上放着一个洗笔的杯子，水是浑的，反着光。旁边是一盆干了一半的绿萝。"},{"t":"n","text":"台灯是旧的，灯罩歪着，光从她侧面打过去，把她的影子投在墙上，很大。"},{"t":"n","text":"你站在树下，仰头看。"},{"t":"n","text":"她没有拉窗帘。她画得很专注，偶尔停下来，退后一点看，再凑近。"},{"t":"n","text":"有一次她抬头，像是要看窗外。"},{"t":"n","text":"你来不及躲。她看见你了。"},{"t":"n","text":"她看了你两秒。没有拉窗帘，也没有生气。"},{"t":"n","text":"她低下头，接着画。"},{"t":"n","text":"你站了一会儿，走了。走到巷口，你回头，那扇窗还亮着。"},{"t":"n","text":"你想起你柜子里的画。想起那张被妈妈贴在墙上的奖状，正好盖住了你画的一棵树。"},{"t":"n","text":"同学的妈妈送你到楼下，说：「考不上也没事。人好好的，比什么都强。」"},{"t":"n","text":"你说了声谢谢。你想，你妈不会这么说。"},{"t":"n","text":"走到巷口，你回头看了一眼三楼。她换了个姿势，把画布往灯下挪了挪。"},{"t":"n","text":"回到家，你妈妈还在客厅等你。她问：「资料借到了？」"},{"t":"n","text":"你说借到了。她说：「那就好。快去洗脚。」"},{"t":"n","text":"你回到房间，翻开那本资料。扉页是空白的，你拿起笔，画了一棵树。"},{"t":"n","text":"画完你看了一会儿，又用橡皮擦掉。擦得不干净，留了一点印子。"},{"t":"n","text":"你对自己说，等考完试再画。"},{"t":"n","text":"你考完试，又对自己说，等上了高中再说。"},{"t":"n","text":"那扇窗的光，你记了很久。比你记住的很多事都久。"},{"t":"n","text":"你后来知道，她家就在那栋楼的三楼，窗外有一排梧桐。"},{"t":"n","text":"风一过，叶子就响。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"在楼下站到灯灭","hint":"把一扇窗记住 · 心情 ↑","eff":{"happy":2.0,"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"你靠在树上，站到十点半。腿有点麻，你没有动。"},{"t":"n","text":"灯是十点四十灭的。灭之前，她站起来，伸了个懒腰，把画布从板上取下来。"},{"t":"n","text":"你在黑暗里站了一会儿，才走。"}]},{"label":"B","text":"记住那扇窗的位置","hint":"记路 · 智力 ↑","eff":{"int":1.0,"happy":1.0},"reply":[{"t":"n","text":"你数了三样东西：三单元，三楼，从左数第二扇窗。"},{"t":"n","text":"你在数学资料的扉页上写下这三个数字，写完自己都觉得奇怪。"},{"t":"n","text":"那三个数字后来在你脑子里放了很久。你没有用过，也没有忘。"}]},{"label":"C","text":"走开","hint":"不打扰 · 情商 ↑","eff":{"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你低下头，继续走。梧桐的影子一块一块从你脚上过去。"},{"t":"n","text":"走出很远，你还是觉得那扇窗在背后亮着。"},{"t":"n","text":"你没有回头。"}]}]},{"t":"n","text":"第二年夏天，中考结束。你又路过那栋楼。"},{"t":"n","text":"窗开着，晾着一件校服。蓝白的，袖口有一道洗不掉的绿。"},{"t":"n","text":"是你要去的那所高中的校服。"},{"t":"n","text":"你站在楼下看了一会儿，忽然觉得，高中好像没有那么难熬。"},{"t":"n","text":"开学那天，你在新生名单上找过她的名字。"},{"t":"n","text":"人太多，名单很长，你找到一半就放弃了。"},{"t":"n","text":"后来你在社团招新的时候看见她，才想起那扇窗。"}],"id":"jiangwan_04"}]},{"id":"ch1","title":"第一章 · 高中","scenes":[{"no":5,"title":"三块钱的名字","week":3,"bg":"court_day","cast":["jiangwan","chengye"],"steps":[{"t":"cast","list":["jiangwan","chengye"],"focus":"jiangwan"},{"t":"n","text":"社团招新在操场，各班搬桌子出来，桌子一排一排，像临时搭起来的街。"},{"t":"n","text":"体育社在最前面，程野站在桌子上喊，嗓子已经哑了。文学社在中间，一个男生在念诗，念到一半忘了词。"},{"t":"n","text":"美术社和文学社共用一张桌子。桌布是两块拼的，一块蓝，一块绿。"},{"t":"n","text":"江晚坐在桌子后面，低着头，在画一张报名表背面的空白。"},{"t":"n","text":"她穿灰绿色的衬衫，袖子挽到手肘，右手食指侧面有一道淡淡的墨。头发很长，垂下来，把脸挡了一半。"},{"t":"n","text":"你走到桌前。她没抬头，笔尖在纸上走。"},{"t":"n","text":"停了两秒，她忽然说：「你叫……」"},{"t":"n","text":"她念出你的名字。念得很准。"},{"t":"n","text":"然后她抬起头。"},{"t":"c","id":"jiangwan","text":"三块钱。"},{"t":"n","text":"你没反应过来。她把笔放下，从桌肚里拖出一个铁皮颜料盒，打开。"},{"t":"n","text":"十二个格子，九个是空的。半管钴蓝躺在最右边，盖子裂了，用透明胶缠了两圈。"},{"t":"c","id":"jiangwan","text":"这个牌子的蓝，现在十四块。"},{"t":"n","text":"她说的是价格，不是谢谢。你后来才知道，她习惯把欠着的东西换算成具体的数，这样才还得清。"},{"t":"n","text":"她把社团登记表推过来，纸角压着一本速写本，封皮上有一圈咖啡渍。"},{"t":"c","id":"jiangwan","text":"美术社周三、周五开。画室在艺术楼四楼，钥匙在我这。"},{"t":"n","text":"她顿了一下，补了一句：「不用自带颜料。我有。」"},{"t":"n","text":"她说「我有」的时候，语气很平，像在说一件很确定的事。"},{"t":"n","text":"旁边文学社的男生探过头来：「同学，文学社也考虑一下？对作文有帮助。」"},{"t":"n","text":"江晚把文学社的表抽过来，垫在画下面。"},{"t":"c","id":"jiangwan","text":"文学社是我妈让报的。她说对作文有好处。"},{"t":"n","text":"她说这话时没有不高兴，也没有解释。"},{"t":"n","text":"程野从前面那张桌子上跳下来，球夹在胳膊底下，走过来拍你的肩。"},{"t":"c","id":"chengye","text":"美术社？你还画画啊。"},{"t":"n","text":"他看了一眼江晚，又看了一眼那张登记表，笑了一下，跑回去了。"},{"t":"n","text":"江晚没抬头。她在画一个东西，笔尖转得很快。"},{"t":"n","text":"你看见她画的是刚才那个念诗的男生，画成一只站着打瞌睡的鹤。"},{"t":"n","text":"她把那一页撕下来，折了两折，塞进桌肚，像在处理什么不该留下的东西。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"报美术社","hint":"画室常开 · 创造力 ↑","eff":{"aff":6.0,"cre":3.0,"happy":2.0},"reply":[{"t":"n","text":"你在美术社那一栏写下名字。她看着你写，写完了，把表拿过去，吹了吹没干的墨。"},{"t":"c","id":"jiangwan","text":"周三下午，四点半。别迟到。"},{"t":"n","text":"她把你的名字又描了一遍，描得很重。"}]},{"label":"B","text":"报文学社","hint":"先读点东西 · 情商 ↑","eff":{"aff":4.0,"eq":3.0,"happy":1.0},"reply":[{"t":"n","text":"你报了文学社。她「哦」了一声，把笔帽扣上。"},{"t":"c","id":"jiangwan","text":"也行。文学社在二楼，离画室近。"},{"t":"n","text":"她把速写本翻开，撕下一角，写了一个地址和一个时间，塞给你。"},{"t":"n","text":"那张纸后来在你钱包里放了三年。"}]},{"label":"C","text":"先不报，来画室看看","hint":"留一条退路 · 心情 ↑","eff":{"aff":2.0,"happy":2.0},"reply":[{"t":"n","text":"你说，先看看。她点头，把登记表收回去。"},{"t":"c","id":"jiangwan","text":"看也行。看不用交钱。"},{"t":"n","text":"她把颜料盒合上，扣扣子的时候扣了两次才扣上。"},{"t":"n","text":"你走开几步，回头，看见她又低下头，接着画那张报名表背面。"}]}]},{"t":"n","text":"招新结束，桌子一张一张搬回去。她一个人搬那块蓝桌布，拖在地上。"},{"t":"n","text":"你过去帮她抬另一头。她说：「不用。」但没松手。"},{"t":"n","text":"走到艺术楼楼下，她把桌布往肩上一搭，说：「登记表我交上去了。你名字最后一个字，是哪个？」"},{"t":"n","text":"你说了。她点点头，转身上楼，脚步很轻。"},{"t":"n","text":"登记表在她手里，卷成一个筒。她走到楼梯拐角，用那个筒敲了敲栏杆，敲了两下。"},{"t":"n","text":"你后来才知道，那是她高兴的时候才会做的事。"},{"t":"n","text":"那天下午的太阳很好。操场上都是人，扩音器里在放一首很吵的歌。"}],"id":"jiangwan_05"},{"no":6,"title":"报纸糊窗","week":6,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"家长会是周四晚上。楼下的教室亮着灯，一排一排的家长坐在自己孩子的座位上。"},{"t":"n","text":"你上楼拿落下的书，路过四楼，看见画室的门开了一条缝。"},{"t":"n","text":"她坐在窗台上，腿垂着，手里拿着一卷报纸和一碗浆糊。"},{"t":"n","text":"画室的窗是老式的木框，关不严，冬天漏风。风从缝里进来，把窗台上的画纸吹得翻角。"},{"t":"n","text":"她把报纸摊在膝盖上，撕成一条一条，抹上浆糊，往缝上贴。"},{"t":"c","id":"jiangwan","text":"你来得正好。帮我扶着。"},{"t":"n","text":"你扶住报纸。她的手很凉，指尖有浆糊，白白的。"},{"t":"n","text":"走廊那头传来声音。是她妈妈，在跟班主任说话。声音不大，但走廊太空，字字都清楚。"},{"t":"n","text":"「她成绩中游，不算差。画画当个爱好就行，别耽误正事。」"},{"t":"n","text":"「师范，稳当。女孩子，稳当最要紧。」"},{"t":"n","text":"「她从小就这样，喜欢画。我们也不拦着，就是不能当饭吃。」"},{"t":"n","text":"她贴报纸的手停了一下，又继续贴。浆糊刷得比刚才厚。"},{"t":"n","text":"你没说话。她也没说。"},{"t":"n","text":"过了一会儿，她开口，声音很轻。"},{"t":"c","id":"jiangwan","text":"我妈不是坏人。"},{"t":"n","text":"她把一条报纸按在窗框上，按了很久才松手。"},{"t":"c","id":"jiangwan","text":"她就是算过账。她教了二十三年书，见过太多人。"},{"t":"n","text":"她低头，把浆糊碗往旁边挪了挪。"},{"t":"c","id":"jiangwan","text":"她算得没错。画画的人里，十个有九个养不活自己。"},{"t":"n","text":"她说这话的时候很平静。平静得像在说别人家的事。"},{"t":"n","text":"窗缝堵上一条，风小了一点。屋里还是冷，但冷得慢了。"},{"t":"n","text":"画室门口的地上放着两个橘子，用塑料袋装着，袋口打了个结。"},{"t":"n","text":"是她妈妈放的。人已经下楼了。"},{"t":"n","text":"她看了一眼那个塑料袋，没动。"},{"t":"n","text":"「她总是这样。」她说，「不说，就放点东西。」"},{"t":"n","text":"你问，那你妈知道你在这儿吗。"},{"t":"n","text":"她想了想，说：「知道。她看见我上楼了。」"},{"t":"n","text":"窗缝堵上一条，风小了一点。浆糊在指尖上干得很快，绷着一层。"},{"t":"n","text":"她伸手，把浆糊从指头上搓下来，搓成一个小球，弹进垃圾桶。"},{"t":"n","text":"没弹中，球滚到画架底下去了。她看了两秒，没去捡。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她糊窗","hint":"先把风挡住 · 心情 ↑","eff":{"aff":5.0,"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"你接过浆糊碗，蹲下来贴下面那一排。她贴上面。"},{"t":"n","text":"贴到一半，你才发现报纸是去年的，上面有她画的圈，圈着一个招生广告。"},{"t":"n","text":"她瞥了一眼，说：「那是我妈圈的。师范。」"},{"t":"n","text":"你把那张报纸正过来，贴在最显眼的地方。"}]},{"label":"B","text":"说「你画得真好」","hint":"说句好听的 · 好感 ↑","eff":{"aff":3.0,"cha":1.0,"happy":1.0},"reply":[{"t":"n","text":"你说，你画得真好。"},{"t":"n","text":"她把浆糊刷停在空中，看了你两秒。"},{"t":"c","id":"jiangwan","text":"好，和真好，中间差着挺远的。"},{"t":"n","text":"她把刷子放下，说：「不过谢谢。」"},{"t":"n","text":"她说谢谢的时候，没有笑。但也没有不高兴。"}]},{"label":"C","text":"问她「那你想怎么办」","hint":"问她 · 情商 ↑","eff":{"aff":4.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你问她，那你想怎么办。"},{"t":"n","text":"她想了很久。久到浆糊在碗里结了一层皮。"},{"t":"c","id":"jiangwan","text":"我想画。可是我不知道，我想画的那些，有没有人要。"},{"t":"n","text":"她说完，把最后一条报纸贴上，用手掌压平。"},{"t":"c","id":"jiangwan","text":"这话我没跟别人说过。"}]}]},{"t":"n","text":"窗全糊完了。屋里暗下来，糊了报纸的窗透进一点走廊的灯，黄的，很软。"},{"t":"n","text":"她跳下窗台，把浆糊碗端去水池。路过门口，她弯腰把两个橘子捡起来，放进口袋。"},{"t":"n","text":"走到楼梯口，她回过头。"},{"t":"c","id":"jiangwan","text":"今天的事，你别跟我妈说。"},{"t":"n","text":"你说好。她点点头，下楼了。"},{"t":"n","text":"两个橘子，她一个也没吃。第二天，它们出现在画室的窗台上，皮已经有点干了。"},{"t":"n","text":"过了两天，橘子少了一个。你问她是不是吃了，她说：「放着也是坏。」"},{"t":"n","text":"另一只一直在窗台上，放到皮皱得像一张纸。她没扔，也没吃。"},{"t":"n","text":"那年冬天很冷。画室的暖气不热，她戴着一副露指手套画画，画两笔搓一下手。"},{"t":"n","text":"她说，手冷了，颜色就调不准。"}],"id":"jiangwan_06"},{"no":7,"title":"六米的布","week":14,"bg":"gym_hall","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"礼堂的舞台背景是一块六米长的布，从顶上垂下来，一直拖到地板。"},{"t":"n","text":"布上画着一整片麦田，天压得很低，云是铅灰的。角落里有一行很小的字，你凑近才看清：高二（三）班，江晚。"},{"t":"n","text":"她画了三个通宵。第三个通宵，她在画室睡着了，脸压在调色盘上，第二天额头上有一块土黄。"},{"t":"n","text":"演出七点开始。五点半，道具组搬铁架子，架子的一角刮过布面。"},{"t":"n","text":"从上到下，裂开一条口子，一米多长。布太薄，裂口边缘卷起来。"},{"t":"n","text":"她赶到的时候，后台很吵。有人在试音响，有人在找服装。"},{"t":"n","text":"她站在那块布前面，没有喊，也没有哭。"},{"t":"n","text":"她蹲下来，用手指量那道口子的长度。"},{"t":"c","id":"jiangwan","text":"这块布一百二。学校只报一半。"},{"t":"n","text":"学生会干事跑过来，看了一眼，说：「要不先挂着？观众离得远，看不出来。」"},{"t":"n","text":"她摇头。"},{"t":"n","text":"她从书包里拿出一个针线包。针是提前别在袖口上的，一共三根。"},{"t":"n","text":"她开始缝。针脚很密，一边缝一边把布往中间收，收出一道褶。"},{"t":"n","text":"缝到一半，她忽然停下来，看着那道被收起来的褶。"},{"t":"c","id":"jiangwan","text":"这块，可以画成河。"},{"t":"n","text":"她抬头看你。"},{"t":"c","id":"jiangwan","text":"麦田边上，本来应该有一条河。我画的时候忘了。"},{"t":"n","text":"离开演还有一小时二十分钟。颜料箱在画室，跑一个来回要八分钟。"},{"t":"n","text":"后台很乱。主持人在角落里背词，背两句看一眼手卡。舞蹈队的孩子挤在镜子前面，有人在哭。"},{"t":"n","text":"一个女生跑过来问：「江晚，那个背景怎么办？」她说：「我想办法。」"},{"t":"n","text":"针线包是那种最便宜的，塑料盒，盖子裂了，里面的线缠成一团。"},{"t":"n","text":"她挑出一根白线，对着灯穿针。穿了一次，没进去。第二次，她把线头在嘴里抿了一下，穿进去了。"},{"t":"n","text":"「这个布太薄。」她一边缝一边说，「一拉就变形。不能拉太紧。」"},{"t":"n","text":"她缝了几针，停下来，把布往中间推了推，再缝。"},{"t":"n","text":"针脚开始歪，后来慢慢直了。"},{"t":"n","text":"学生会干事又过来，说：「要不就这样吧，观众真的看不出来。」"},{"t":"n","text":"她没抬头。"},{"t":"c","id":"jiangwan","text":"我看得出来。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"站到布后面撑住","hint":"先撑起来 · 体魄 ↑","eff":{"aff":4.0,"str":2.0,"happy":2.0},"reply":[{"t":"n","text":"你绕到布后面，用肩膀顶住那道褶。布很薄，你能看见前面的光。"},{"t":"n","text":"她隔着布说：「往左一点。」你往左。她又说：「再左。」你又往左。"},{"t":"n","text":"她的声音闷闷地传过来，像从很远的地方。"}]},{"label":"B","text":"提议把破口画成河","hint":"换个画法 · 创造力 ↑","eff":{"aff":6.0,"cre":3.0,"happy":2.0},"reply":[{"t":"n","text":"你说，别缝死了。留着这道褶，画成河。"},{"t":"n","text":"她看着你，眼睛慢慢亮起来。"},{"t":"c","id":"jiangwan","text":"你怎么想的。"},{"t":"n","text":"你说不知道，就是觉得，破了的地方也可以留着。"},{"t":"n","text":"她低头，把缝到一半的线拆了两针。"}]},{"label":"C","text":"去后台找老师说明","hint":"把话说清楚 · 情商 ↑","eff":{"aff":3.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你跑到后台找负责老师。老师正在对流程表，头也没抬：「知道了。先演，演完再说。」"},{"t":"n","text":"你回来的时候，她已经自己缝了一半。"},{"t":"n","text":"她看你一眼，说：「没事。我习惯了。」"}]}]},{"t":"n","text":"七点整，灯暗下来。布上的麦田被灯光一照，铅灰的云变成了暖的。"},{"t":"n","text":"那道褶被画成了一条河，从麦田中间穿过去，一直流到台口。"},{"t":"n","text":"演出结束，掌声响起来。幕布慢慢落下，盖住那条河。"},{"t":"n","text":"后台很挤。她站在水池边洗手，水是黑的，颜料一层一层化开。"},{"t":"c","id":"jiangwan","text":"刚才那一段，没有人看见。"},{"t":"n","text":"你说，你看见了。"},{"t":"n","text":"她关掉水龙头，甩了甩手上的水，没接话。"},{"t":"n","text":"过了一会儿，她说：「谢谢。」"},{"t":"n","text":"那根针还别在她袖口上。回去的路上，她一直没取下来。"},{"t":"n","text":"第二天上课，你看见那根针还在。第三天也在。"},{"t":"n","text":"后来那件校服的袖口上，留下了一个很小的孔。"}],"id":"jiangwan_07"},{"no":8,"title":"三百块的墙","week":16,"bg":"cafe","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"奶茶店在学校后门，两间门面，墙上原本贴着一张褪色的海报。"},{"t":"n","text":"老板要一整面墙，四米宽，两米五高，画云，画猫，画得可爱一点。"},{"t":"n","text":"「粉的。」老板说，「现在小姑娘都喜欢粉的。」"},{"t":"n","text":"她站在墙前面，仰头看了很久，然后从书包里拿出一个本子，算账。"},{"t":"n","text":"丙烯八十，滚筒十五，美纹纸十块，来回公交八块。三百减去这些，剩一百八十七。"},{"t":"n","text":"两天。一天九十多块。"},{"t":"n","text":"她把本子合上，说：「行。」"},{"t":"n","text":"周六早上八点，你到的时候，她已经把墙根用旧报纸铺好了。"},{"t":"n","text":"她穿一件很旧的T恤，头发扎起来，用一支笔别着。"},{"t":"c","id":"jiangwan","text":"你负责递东西。别碰墙，手上有油。"},{"t":"n","text":"她起稿用的是粉笔。云一朵一朵，从左边飘到右边，中间留了一块空。"},{"t":"n","text":"猫画在空的地方，趴着，尾巴垂下来，尾巴尖卷了一下。"},{"t":"n","text":"粉色调了三次。第一次太甜，第二次发灰，第三次她加了一点黄。"},{"t":"c","id":"jiangwan","text":"这个粉，像下午四点的云。"},{"t":"n","text":"她刷得很慢。滚筒走过的地方，墙上的旧海报印子透出来一点，她又盖一层。"},{"t":"n","text":"中午店里忙起来，客人端着奶茶站在门口看，有人举手机拍。"},{"t":"n","text":"一个女生说：「好可爱啊，这是谁画的？」"},{"t":"n","text":"老板指了指她：「我们请的画家。」"},{"t":"n","text":"她背对着人，没回头，耳朵有点红。"},{"t":"n","text":"下午四点，光从门口斜进来，照在那只猫的尾巴上。她退后几步，看了很久。"},{"t":"n","text":"收工是周日傍晚。老板绕着墙走了一圈，蹲下来看墙根。"},{"t":"n","text":"「这儿弄脏了。」他指着地上一点粉色，「扣二十。」"},{"t":"n","text":"她从口袋里掏出一张纸，把墙角那块擦干净，站起来。"},{"t":"c","id":"jiangwan","text":"行。"},{"t":"n","text":"老板数了两百八，递过来。她一张一张点，点完折好，放进书包内袋。"},{"t":"n","text":"出了店门，她没说报复的话，也没说下次不接。"},{"t":"n","text":"走到画材店，她进去买了三管钛白，一支圆头笔。出来的时候，袋子提在手里，一晃一晃。"},{"t":"c","id":"jiangwan","text":"以前我画画是花钱。现在能挣一点了。"},{"t":"n","text":"她说这话的时候在看路，不是看你。"},{"t":"n","text":"走了一段，她忽然停下来。"},{"t":"c","id":"jiangwan","text":"可是我今天一直在画别人想要的东西。"},{"t":"n","text":"她低头看自己的手。指甲缝里是粉色的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「这也不算浪费」","hint":"承认它的价值","eff":{"aff":3.0,"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"你说，至少这面墙会有人看见，会有人因为一只猫高兴一下。"},{"t":"n","text":"她想了想，说：「也是。」"},{"t":"n","text":"她把袋子换了一只手提，说：「一百八十七块。够我买四管好白，或者一块小画布。」"}]},{"label":"B","text":"问她「你自己想画什么」","hint":"问她自己 · 情商 ↑","eff":{"aff":5.0,"eq":2.0,"cre":1.0},"reply":[{"t":"n","text":"你问她，那你自己想画什么。"},{"t":"n","text":"她想了很久。路灯亮了，她的影子被拉得很长。"},{"t":"c","id":"jiangwan","text":"我想画那种，看完以后会安静下来的东西。"},{"t":"n","text":"她抬手，指了指天边最后一小块亮。"},{"t":"c","id":"jiangwan","text":"不是这种粉。是更远一点的。"}]},{"label":"C","text":"说「以后别接这种」","hint":"替她心疼 · 心情 ↓","eff":{"aff":1.0,"happy":-1.0,"eq":1.0},"reply":[{"t":"n","text":"你说，以后别接这种活了。"},{"t":"n","text":"她笑了一下，笑得有点短。"},{"t":"c","id":"jiangwan","text":"那你养我啊。"},{"t":"n","text":"说完她自己先摆手：「开玩笑的。颜料很贵的。」"},{"t":"n","text":"她低头，把书包带子往上提了提，没再说话。"}]}]},{"t":"n","text":"快到学校的时候，她从口袋里摸出两张十块的，塞给你。"},{"t":"n","text":"你说不用。她把手收回去，又伸出来，钱还是那两张。"},{"t":"c","id":"jiangwan","text":"你今天帮我递了两天颜料。这不是客气，是工钱。"},{"t":"n","text":"你收下了。钱是新的，边角很硬。"},{"t":"n","text":"她走了两步，回头补了一句：「下次有活，我还叫你。」"},{"t":"n","text":"她说到做到。后来那个学期，她又接了两次墙绘：一次是宠物店，一次是理发店。"},{"t":"n","text":"宠物店那次画的是一只金毛，画得太大，几乎占了半面墙。"},{"t":"n","text":"老板说：「太大了。」她说：「狗本来就大。」"},{"t":"n","text":"最后没有改。老板付了钱，说：「行吧，挺显眼的。」"}],"id":"jiangwan_08"},{"no":9,"title":"画架搬走","week":22,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"通知贴在画室门上，A4 纸，打印的：因高三复习需要，本室自下周起改为自习室，请于三日内清空个人物品。"},{"t":"n","text":"纸上盖了一个红章，章盖歪了。"},{"t":"n","text":"画室里堆着七八个画架，有的落满灰，有的还夹着没画完的纸。"},{"t":"n","text":"她的画架在最里面，靠窗。木头的，边角磨得发亮。"},{"t":"n","text":"你到的时候，她正在拆。六角螺丝，一颗一颗拧下来，放进一个铁盒里。"},{"t":"c","id":"jiangwan","text":"来得正好。扶一下。"},{"t":"n","text":"画架的一条腿比别的短，底下垫着一本旧杂志。杂志卷了边，封面是一本时装画报。"},{"t":"n","text":"你把杂志抽出来，翻开。里面每一页的空白处都画满了——手、脚、椅子、窗、一只反复出现的猫。"},{"t":"n","text":"她把杂志拿过去，卷起来，塞进书包。"},{"t":"c","id":"jiangwan","text":"垫了三年。有点感情。"},{"t":"n","text":"画架拆成四根木头，用绳子捆成一捆。她把绳子绕了三圈，打了个死结。"},{"t":"n","text":"还有颜料、画笔、一沓画纸、半箱旧画布。两个人搬了两趟。"},{"t":"n","text":"第三趟上去，她站在空下来的窗边，没有立刻走。"},{"t":"n","text":"窗台上有一圈一圈的颜料印，像树的年轮。"},{"t":"n","text":"她说：「上去看看？」"},{"t":"n","text":"天台的门在楼梯尽头，铁门，锁坏了，用一根铁丝绕了两圈。"},{"t":"n","text":"她把铁丝解开，推开门。风一下子灌进来。"},{"t":"n","text":"天台上有水塔、几根晾衣绳、一盆干死的植物。城市在下面，房子一片一片，灰的。"},{"t":"n","text":"她走到边上，往下看。风把她的头发全吹到一边。"},{"t":"n","text":"她看了很久，然后说：「这上面挺好。没人管。」"},{"t":"n","text":"你问她，报了文科还是理科。"},{"t":"n","text":"她说文科。她说她妈已经把师范的分数线问好了，去年的，抄在一张纸上，贴在冰箱上。"},{"t":"c","id":"jiangwan","text":"我妈说，考上了就给我买一台新电脑。她不知道美术生也要电脑。"},{"t":"n","text":"她笑了一下，笑意没到眼睛。"},{"t":"c","id":"jiangwan","text":"我跟她说，我先把这一年过完。"},{"t":"n","text":"你没有接话。风把晾衣绳吹得响，一下一下，像有人在敲。"},{"t":"n","text":"过了一会儿，她说：「其实画画这事，停一年也没什么。」"},{"t":"n","text":"她低头，把脚边一块小石子踢到墙根。"},{"t":"c","id":"jiangwan","text":"画不会跑。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把画架搬回家","hint":"把东西收好 · 好感 ↑","eff":{"aff":5.0,"str":2.0,"happy":2.0},"reply":[{"t":"n","text":"你说，我帮你把画架搬回去。"},{"t":"n","text":"她看了你一眼，说：「我家在六楼，没电梯。」"},{"t":"n","text":"你说没事。她也没再推。"},{"t":"n","text":"画架扛在肩上，四根木头硌得慌。她走在前面，替你开门，替你按亮楼道的灯。"},{"t":"n","text":"她家在六楼。门口摆着一双很小的拖鞋，是她的。"},{"t":"n","text":"她妈妈开门，看见画架，愣了一下，侧身让你们进去。"}]},{"label":"B","text":"说「考完再画，画不会跑」","hint":"先过这一关","eff":{"aff":2.0,"int":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你说，考完再画也一样。画不会跑。"},{"t":"n","text":"她把石子踢得更远了一点。"},{"t":"c","id":"jiangwan","text":"画不会跑。手会。"},{"t":"n","text":"她说完就转身下楼了，脚步比平时快。"},{"t":"n","text":"你跟下去，看见她站在画室门口，看着那面空了的窗台。"}]},{"label":"C","text":"什么也不说，陪她站到天黑","hint":"不说话也行 · 心情 ↑","eff":{"aff":4.0,"happy":3.0,"eq":1.0},"reply":[{"t":"n","text":"你没说话。她也没说。"},{"t":"n","text":"太阳落到楼后面，天从白变成灰，再变成一点橘。"},{"t":"n","text":"她忽然说：「这个颜色，叫赭石。加一点白，就是云。」"},{"t":"n","text":"你说，记住了。"},{"t":"n","text":"她说：「不用记。看看就行。」"}]}]},{"t":"n","text":"下楼的时候，天已经暗了。画架靠在楼道拐角，绳子还是那个死结。"},{"t":"n","text":"她锁了画室的门，把钥匙在手里掂了两下。"},{"t":"n","text":"走到楼梯口，她忽然停下。"},{"t":"c","id":"jiangwan","text":"这栋楼的天台，我以后还会来。"},{"t":"n","text":"你说，那门锁坏了。"},{"t":"c","id":"jiangwan","text":"所以才会来。"},{"t":"n","text":"她把钥匙放进口袋，下楼。走到二楼，她抬头喊了一声：「开学见。」"},{"t":"n","text":"声音在楼道里弹了两下，就没了。"},{"t":"n","text":"你站在楼梯上，听见她下到一楼，推开单元门。门轴响了一声，又合上。"},{"t":"n","text":"外面的天已经全黑了。"}],"id":"jiangwan_09"}]},{"id":"ch2","title":"第二章 · 大学","scenes":[{"no":10,"title":"颜料贵三倍","week":26,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"美院在省城的西边，红砖楼，墙上爬着爬山虎，一直爬到四楼。"},{"t":"n","text":"你坐了两个小时的车。到的时候是上午十点，她已经在门口等了。"},{"t":"n","text":"她穿一件宽大的灰绿衬衫，头发扎起来，手里拎着一个帆布袋，袋子底部有一圈洗不掉的颜料。"},{"t":"c","id":"jiangwan","text":"先跟我去上班。"},{"t":"n","text":"画材店在美院后门的地下一层，楼梯很陡，墙上贴着一张「颜料清仓」的纸。"},{"t":"n","text":"她在店里做兼职，周六一天，一小时十五块。工作内容是理货、擦架子、给来买颜料的学生找色号。"},{"t":"n","text":"老板娘认识她，把钥匙扔给她，说：「地下室那箱过期的，你自己看，能用的拿走。」"},{"t":"n","text":"她蹲在箱子边翻了很久，翻出三管还能挤动的土黄，用纸巾擦干净管口，放进帆布袋。"},{"t":"c","id":"jiangwan","text":"过期的土黄会结块，加一点水还能用。"},{"t":"n","text":"她说这话的时候很自然，像在说一件人人都会做的事。"},{"t":"n","text":"中午她带你去吃面。店在巷子里，八块一碗，桌子是折叠的。"},{"t":"n","text":"她点了素面，把碗里仅有的两片牛肉夹到你碗里。"},{"t":"n","text":"你说你自己有。她说：「我不爱吃牛肉。」"},{"t":"n","text":"她说不爱吃的时候，眼睛看着别处。"},{"t":"n","text":"吃完饭，她带你去看她住的地方。校外的老居民楼，六楼，一间房隔成两半，住了六个人。"},{"t":"n","text":"她的床在上铺。床头贴着一张纸，写着这个月的开支：房租四百五，画布四十五，颜料一百二，饭钱三百。"},{"t":"n","text":"阳台很小，晾着一排洗过的画笔，笔尖朝下，水一滴一滴落在水泥地上。"},{"t":"n","text":"她的调色盘是一块玻璃，边缘用胶带缠了，是从家里带来的。"},{"t":"c","id":"jiangwan","text":"买一个要四十。玻璃好用，刮得干净。"},{"t":"n","text":"你问她，画一张要多久。"},{"t":"n","text":"她说，小的三天，大的一个月。她又说，画布的钱是提前垫的，卖不出去就一直在那儿。"},{"t":"n","text":"她说这些的时候没有抱怨的意思。她在报账。"},{"t":"n","text":"她带你去看她画画的地方。阳台封了一半，放着一个画架，画架上是一张没画完的城市。"},{"t":"n","text":"灰的楼，灰的天，只有一扇窗是亮的，橘色。"},{"t":"n","text":"她说这张画了两个月。白天要上班，晚上才有光。"},{"t":"n","text":"室友从房间里出来，端着泡面，跟她打了个招呼，又进去了。"},{"t":"n","text":"她压低声音说：「她们睡得早。我晚上画，只能画丙烯，油画味道太大。」"},{"t":"n","text":"她说这话的时候，把画架往边上挪了挪，好像怕挡着谁。"},{"t":"n","text":"栏杆上晾着三块洗过的画布，用夹子夹着，风吹得鼓起来。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把画框搬上楼","hint":"出点力气 · 好感 ↑","eff":{"aff":4.0,"str":2.0,"happy":2.0},"reply":[{"t":"n","text":"楼下堆着六个画框，是别人订了又不要的，她捡回来的。"},{"t":"n","text":"两个人搬，一趟两个，爬六楼。搬到第四趟，你的手在抖。"},{"t":"n","text":"她在楼上喊：「歇会儿。框不会跑。」"},{"t":"n","text":"你说这句话听着耳熟。她愣了一下，笑了。"}]},{"label":"B","text":"请她吃一顿贵的","hint":"让她歇一晚 · 心情 ↑","eff":{"aff":3.0,"fin":-3.0,"happy":3.0},"reply":[{"t":"n","text":"晚上你带她去商场里的一家店。她看菜单看了很久，点了一个最便宜的。"},{"t":"n","text":"你说，随便点。她抬头看你一眼，又低头，加了一个汤。"},{"t":"n","text":"结账的时候她抢着付，被你按住。出门以后她说：「下次我请。真的。」"}]},{"label":"C","text":"问她「你后悔吗」","hint":"问一句 · 情商 ↑","eff":{"aff":5.0,"eq":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你问她，后悔吗。"},{"t":"n","text":"她把筷子放下，想了一会儿。"},{"t":"c","id":"jiangwan","text":"后悔是奢侈品。"},{"t":"n","text":"她端起碗，把汤喝完，放下。"},{"t":"c","id":"jiangwan","text":"我要是有空后悔，不如多画一张。"}]}]},{"t":"n","text":"下午的车是四点半。她送你到公交站，从帆布袋里拿出一张明信片。"},{"t":"n","text":"正面是美院的红砖楼，背面写着一行字，字很小。"},{"t":"n","text":"你上车以后才翻过来看。上面写着：这里的颜料比高中贵三倍。"},{"t":"n","text":"没有别的。没有「想你了」，也没有「什么时候再来」。"},{"t":"n","text":"你把明信片放进钱包。公交车拐弯的时候，你看见她还站在站牌下，手插在口袋里。"}],"id":"jiangwan_10"},{"no":11,"title":"画室的天台","week":28,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"画室在艺术楼顶层，夏天热，冬天冷，窗子关不严。江晚说，这样颜料干得慢，正好。"},{"t":"n","text":"推门进去，一股松节油和旧纸的味道。灯只开了一盏，照着画架。"},{"t":"n","text":"她坐在窗边，背对着门。画布上是一片还没画完的黄昏，橘和蓝搅在一起，云压得很低。"},{"t":"n","text":"天已经黑了。窗外只剩下教学楼的白灯，一格一格亮着。"},{"t":"n","text":"手机倒扣在颜料盒旁边，屏幕还亮着，是通话结束的界面。"},{"t":"n","text":"通话时长：四十二分钟。"},{"t":"c","id":"jiangwan","text":"你来得正好。帮我看看，这个蓝是不是太亮了。"},{"t":"n","text":"你走过去。画里的天，比窗外的天要亮一点。亮得有点像下午四点。"},{"t":"n","text":"你说，比外面亮。"},{"t":"n","text":"她「嗯」了一声，把画笔在洗笔筒里搅了搅。水是浑的，浮着一层油。"},{"t":"c","id":"jiangwan","text":"我妈说，画画不能当饭吃。"},{"t":"n","text":"她说得很轻，像在说别人的事。"},{"t":"c","id":"jiangwan","text":"我说，可是我已经吃了三年了。"},{"t":"n","text":"她笑了一下。笑完，脸上的表情就收回去了。"},{"t":"n","text":"她把画笔提起来，水顺着笔杆往下滴，滴在报纸上。"},{"t":"c","id":"jiangwan","text":"她今天问我，毕业以后怎么办。我说还没想好。她说，那就考编。"},{"t":"n","text":"她停了一下。"},{"t":"c","id":"jiangwan","text":"我说，我不考。"},{"t":"n","text":"你问，那她怎么说。"},{"t":"c","id":"jiangwan","text":"她说，你先考，考完再说。"},{"t":"n","text":"她低头，把画笔在报纸上蹭了两下。"},{"t":"c","id":"jiangwan","text":"她没骂我。她就是重复了一遍分数线。"},{"t":"n","text":"画室很静。楼下有人在打篮球，球撞在篮板上的声音一下一下传上来。"},{"t":"n","text":"她把手伸到灯下，看自己的指甲。指甲缝里嵌着蓝。"},{"t":"c","id":"jiangwan","text":"我今天说得很小声。小到我妈可能没听见。"},{"t":"n","text":"她抬眼看你。"},{"t":"c","id":"jiangwan","text":"你说，一个人要是连自己想干什么都不敢大声说，是不是就不算真的想。"},{"t":"n","text":"她没有等你回答，把笔递过来。"},{"t":"c","id":"jiangwan","text":"你来。就一笔。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"接过笔，画一笔","hint":"留下一点颜色 · 创造力 ↑","eff":{"aff":6.0,"cre":3.0,"happy":2.0,"stress":1.0},"reply":[{"t":"n","text":"你接过笔，蘸了一点橘，在云的边上画了一道。"},{"t":"n","text":"画歪了。那道橘太粗，一直拖到画布外面。"},{"t":"n","text":"她看了两秒，笑起来。"},{"t":"c","id":"jiangwan","text":"挺好。这样它就只属于我们两个人了。"},{"t":"n","text":"她把那一笔留着，没有改。"}]},{"label":"B","text":"帮她洗笔","hint":"做点小事 · 心情 ↑","eff":{"aff":4.0,"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"你把洗笔筒端去水池。水很快变蓝，一层一层往下沉。"},{"t":"n","text":"她靠在门边看你，两手插在口袋里。"},{"t":"c","id":"jiangwan","text":"你洗得比我干净。"},{"t":"n","text":"停了一下，她又说：「我妈要是看见，肯定说你比我适合过日子。」"},{"t":"n","text":"说完她自己先笑了。笑到一半，又收住。"}]},{"label":"C","text":"问她「那你想画什么」","hint":"问她自己 · 情商 ↑","eff":{"aff":5.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你问她，那你想画什么。"},{"t":"n","text":"她想了很久。久到灯管闪了一下。"},{"t":"c","id":"jiangwan","text":"我想画那种，看完以后会安静下来的东西。"},{"t":"n","text":"她指了指窗外：「不是这种。是更远一点的。」"},{"t":"n","text":"你问，更远是哪儿。"},{"t":"n","text":"她说：「就是我画不出来、但知道它在的那个地方。」"}]}]},{"t":"n","text":"她站起来，把笔一放，说：「走。带你上去。」"},{"t":"n","text":"天台的门在楼梯尽头，铁门，锁早就坏了，用一截铁丝绕了两圈。"},{"t":"n","text":"她把铁丝解开，推门。风一下子灌进来，把她的头发全部吹到一边。"},{"t":"n","text":"天台不大。一个水塔，几根晾衣绳，两盆干死的植物。"},{"t":"n","text":"真正的黄昏已经没了。天是深蓝的，往下一点是灰，再往下是城市的光。"},{"t":"n","text":"她走到边上，手扶着栏杆，往下看。"},{"t":"c","id":"jiangwan","text":"我找过很多天台。高中的、我家的、考前班那栋楼的。"},{"t":"n","text":"风把她的衬衫吹得贴在背上。"},{"t":"c","id":"jiangwan","text":"这里的风最像我小时候那边。"},{"t":"n","text":"你问，像在哪儿。"},{"t":"n","text":"她抬手，往一个方向指了指。那边是一片居民楼，亮着零星的灯。"},{"t":"c","id":"jiangwan","text":"我家在三楼。窗外有一排梧桐，风一过就响。"},{"t":"n","text":"她把手放下来，插回口袋。"},{"t":"c","id":"jiangwan","text":"我小时候在墙上画过雨。被老师说了。"},{"t":"n","text":"你说，雨是斜的。"},{"t":"n","text":"她转过头，看你。看了很久。"},{"t":"c","id":"jiangwan","text":"……你画过一把伞。"},{"t":"n","text":"她说完就笑，笑得肩膀在抖。"},{"t":"c","id":"jiangwan","text":"我一直以为那是我记错了。原来真有个人。"},{"t":"block","when":"flag1","steps":[{"t":"n","text":"从天台下来，她送你到楼下。楼道的灯是声控的，走两步就灭。"},{"t":"n","text":"到门口，她从口袋里摸出一小管颜料，放进你的口袋。"},{"t":"n","text":"赭石色，很短，纸皮撕掉了一半。"},{"t":"c","id":"jiangwan","text":"这个颜色最便宜，也最不容易脏。"},{"t":"n","text":"她顿了一下。"},{"t":"c","id":"jiangwan","text":"有些颜色，要两个人一起看才算数。"},{"t":"n","text":"她说完就上楼了，脚步很轻。"},{"t":"n","text":"楼道一层一层亮起来，又一层一层灭掉。"},{"t":"n","text":"你走到校门口，才发现那管颜料的盖子没拧紧。口袋内侧染了一小块赭石色。"},{"t":"n","text":"你用手去擦，擦不掉，反而抹开了一点。"}]}],"id":"jiangwan_11"},{"no":12,"title":"走廊最里面","week":31,"bg":"auditorium","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"社团联合展在一号楼一层，走廊两边挂画，尽头摆一张桌子，放留言本。"},{"t":"n","text":"布展从下午开始，一直弄到晚上九点。灯是临时拉的，有两盏不亮。"},{"t":"n","text":"江晚在画室给你留了一个位置，靠窗，光最好。"},{"t":"c","id":"jiangwan","text":"画坏了也没关系。反正颜料是我的。"},{"t":"n","text":"你画了三张速写，一张窗，一张楼梯，一张是她的背影。"},{"t":"n","text":"她把自己的三张画搬过来。小画布，三十乘四十，画的是天台——水塔、晾衣绳、栏杆。"},{"t":"n","text":"三张并排，天从橘色慢慢变成深蓝。"},{"t":"n","text":"指导老师来了，绕着走廊走了一圈，手里拿着一卷标签。"},{"t":"n","text":"走到她的画前面，老师停下来，看了大概十秒。"},{"t":"n","text":"「这三张，挪一下。」老师说，「消防栓那儿空着。」"},{"t":"n","text":"消防栓在走廊最里面，旁边是垃圾桶和一块「小心地滑」的牌子。"},{"t":"c","id":"jiangwan","text":"这儿光线不好。"},{"t":"n","text":"老师说：「展线要统一。你这三张太小，挂中间不齐。」"},{"t":"n","text":"她没再说什么。她蹲下来，把三张画抱起来，抱在怀里。"},{"t":"n","text":"你跟她一起搬。走廊最里面确实暗，灯管坏了一根，剩下那根一闪一闪。"},{"t":"n","text":"她把画挂好，退后几步，看。"},{"t":"n","text":"标签是提前打印的，白纸黑字：江晓，《天台》系列，丙烯。"},{"t":"n","text":"她看了两秒，从口袋里摸出一支笔，把「晓」改成了「晚」。"},{"t":"n","text":"改得很轻，笔画压在打印的字上。"},{"t":"c","id":"jiangwan","text":"打错了。"},{"t":"n","text":"她把笔帽扣上，说：「没事。反正也没几个人看标签。」"},{"t":"n","text":"开幕那天来了三十几个人。有社团的、有老师、有路过的。"},{"t":"n","text":"她站在自己那三张画旁边，手里捏着一支笔，笔都被她捏出汗了。"},{"t":"n","text":"有人问她：「这三张画的是什么？」"},{"t":"n","text":"她说：「天台。」停了一下，又补了一句：「就是楼上那个天台。」"},{"t":"n","text":"那人「哦」了一声，走了。"},{"t":"n","text":"她低下头，把笔换了一只手。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把画挪回原位","hint":"替她争一次 · 好感 ↑","eff":{"aff":6.0,"happy":3.0,"stress":2.0},"reply":[{"t":"n","text":"你走回走廊中间，把消防栓旁边那三张又搬了回来。"},{"t":"n","text":"你把它们挂在原来的位置，稍微错开一点，让三张的高低连成一条斜线。"},{"t":"n","text":"老师过来，看了一眼，说：「行吧。别挡道。」"},{"t":"n","text":"江晚站在旁边，没说话。等老师走了，她才开口。"},{"t":"c","id":"jiangwan","text":"你干嘛。"},{"t":"n","text":"你说，那儿太暗了。"},{"t":"n","text":"她低头看自己的鞋尖，看了很久。"}]},{"label":"B","text":"说「位置不决定画」","hint":"说句实话 · 情商 ↑","eff":{"aff":3.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你说，位置不决定画。"},{"t":"n","text":"她点了点头。"},{"t":"c","id":"jiangwan","text":"你说得对。"},{"t":"n","text":"她把标签按平，又退后一步看。"},{"t":"c","id":"jiangwan","text":"但我还是不高兴。"},{"t":"n","text":"她说完，自己先笑了一下。"}]},{"label":"C","text":"拍下来，发给她","hint":"先留个证据 · 心情 ↑","eff":{"aff":2.0,"happy":1.0,"eq":1.0},"reply":[{"t":"n","text":"你退后几步，把三张画和那块「小心地滑」的牌子一起拍下来，发给她。"},{"t":"n","text":"她点开看，放大，看了很久。"},{"t":"c","id":"jiangwan","text":"你连牌子都拍进去了。"},{"t":"n","text":"她说这话的时候，语气松了一点。"},{"t":"n","text":"后来你把这张照片洗出来，她把它贴在了画室的柜子上。"}]}]},{"t":"n","text":"展览开三天。第一天人最多，第二天开始少，第三天下午只剩几个。"},{"t":"n","text":"最后一天，你去看。她的三张画前面站着一个老人，拎着一袋菜，站了很久。"},{"t":"n","text":"老人看完了，走到留言本前面，写了两行字。"},{"t":"n","text":"她站在走廊另一头，靠着墙，没有过去。"},{"t":"n","text":"等老人走了，她才过去翻留言本。"},{"t":"n","text":"上面写着：「三楼的天，我认得。」"},{"t":"n","text":"她把那页拍了照，把本子合上，放回原处。"},{"t":"n","text":"收展那天下了雨。她拆画的时候很小心，三张一起抱在怀里，用塑料布盖着。"},{"t":"n","text":"走到走廊中间，她回头看了一眼消防栓旁边的墙。那儿的墙皮有一块鼓起来了。"},{"t":"n","text":"她说：「下次不挂这儿了。」"},{"t":"n","text":"你问，挂哪儿。"},{"t":"n","text":"她说：「挂有光的地方。」"},{"t":"n","text":"那三张画后来挂在了她租的房子里，正对着窗。"},{"t":"n","text":"她拍照片给你看，说：「光是从下午三点开始进来的。」"}],"id":"jiangwan_12"},{"no":13,"title":"只是好看","week":34,"bg":"campus_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"名单是晚上八点出的。她发给你一张截图，没有别的话。"},{"t":"n","text":"青年美展初评，入选六十件。她那张《天台·夜》不在里面。"},{"t":"n","text":"你到的时候，她坐在便利店门口的台阶上，手里一瓶酸奶，喝了一半。"},{"t":"n","text":"便利店的门一开一合，冷气扑出来，把她的头发吹起来一点。"},{"t":"n","text":"她把手机递给你。屏幕上是一封邮件，评审意见三行字。"},{"t":"n","text":"「技法熟练，情绪浮于表面。」"},{"t":"n","text":"「画面悦目，缺少问题意识。」"},{"t":"n","text":"「建议继续探索个人语言。」"},{"t":"n","text":"她把意见抄在了速写本上，抄得很工整，像抄课文。"},{"t":"n","text":"你坐下来。台阶有点凉。"},{"t":"c","id":"jiangwan","text":"他们说得挺准的。"},{"t":"n","text":"她把酸奶喝完，把空瓶放在脚边。"},{"t":"n","text":"「悦目。」她重复了一遍这个词，「就是好看。」"},{"t":"n","text":"她低头，看着自己的手。"},{"t":"c","id":"jiangwan","text":"我怕我的画只是好看。"},{"t":"n","text":"她说这句话的时候声音很低，低到你要往前倾一点才听得清。"},{"t":"n","text":"「好看这件事，我十六岁就做到了。」她说，「我们班黑板报都是我画的。老师夸，同学也夸。」"},{"t":"n","text":"她抬头，看马路对面的路灯。"},{"t":"c","id":"jiangwan","text":"可是夸完就完了。没有人会在那张画前面站超过十秒。"},{"t":"n","text":"她把速写本翻开，翻到夹着展览门票的那一页。"},{"t":"n","text":"门票是她的，背面写着日期，还有一行小字：第十一遍。"},{"t":"n","text":"你问，什么第十一遍。"},{"t":"n","text":"她说：「我数了。看一遍，数一遍。有个人的画前面，最多站了三分钟。」"},{"t":"n","text":"她把手机翻过来，给你看入选名单。"},{"t":"n","text":"第一页第三个名字，是她同班的一个女生。画的是拆迁，一整面墙写满「拆」字。"},{"t":"n","text":"「她那张，」江晚说，「技法不如我。」"},{"t":"n","text":"她说完就停住了，好像觉得这句话不好。"},{"t":"n","text":"过了一会儿，她又说：「可是她那张有话说。我这张……只有好看。」"},{"t":"n","text":"酸奶瓶壁上挂着水珠，一滴落下来，落在她的裤子上。"},{"t":"n","text":"她没有擦。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说出你记得的那一幅","hint":"说具体的 · 好感 ↑","eff":{"aff":6.0,"happy":3.0,"eq":2.0},"reply":[{"t":"n","text":"你说，你记得高二文艺汇演那块布。那道被刮破的口子，她把它缝成了一条河。"},{"t":"n","text":"你说，你到现在都记得那条河的颜色，从麦田中间穿过去。"},{"t":"n","text":"她转过头，看你。看了很久。"},{"t":"c","id":"jiangwan","text":"你连这个都记得。"},{"t":"n","text":"你说，你还记得那块布一百二，学校只报一半。"},{"t":"n","text":"她笑了一下，笑到一半，眼睛红了。她抬手揉了一下，说：「风大。」"}]},{"label":"B","text":"说「好看已经很厉害了」","hint":"安慰她 · 心情 ↑","eff":{"aff":2.0,"happy":-2.0,"eq":1.0},"reply":[{"t":"n","text":"你说，好看已经很厉害了。很多人连好看都做不到。"},{"t":"n","text":"她点点头，说：「嗯。」"},{"t":"n","text":"她把酸奶瓶拿起来，又放下，瓶底在台阶上磕了一声。"},{"t":"c","id":"jiangwan","text":"你这个人，真的很会安慰人。"},{"t":"n","text":"她说完，就没再说话。"}]},{"label":"C","text":"问她「那你想画什么」","hint":"问她自己 · 情商 ↑","eff":{"aff":4.0,"eq":2.0,"cre":1.0},"reply":[{"t":"n","text":"你问她，那你想画什么。"},{"t":"n","text":"她把速写本合上，抱在怀里。"},{"t":"c","id":"jiangwan","text":"我想画那种，让人站超过十秒的东西。"},{"t":"n","text":"她顿了一下，说：「可是我连那个东西长什么样都不知道。」"}]}]},{"t":"n","text":"十一点，便利店的店员出来倒垃圾。你们站起来，往学校走。"},{"t":"n","text":"路上很空，梧桐的影子铺在地上，一块一块。"},{"t":"n","text":"走到校门口，她忽然停下来。"},{"t":"c","id":"jiangwan","text":"我十五岁的时候，觉得画得好看就够了。"},{"t":"n","text":"她把速写本换到另一只手。"},{"t":"c","id":"jiangwan","text":"现在觉得不够。可是我不知道还差什么。"},{"t":"n","text":"她说完，进了校门。门卫室的灯照着她的背影，一直照到拐角。"},{"t":"n","text":"你回到宿舍，把那瓶没喝完的酸奶放进了冰箱。"},{"t":"n","text":"第二天早上，它还在那儿。你没有喝，也没有扔。"},{"t":"n","text":"后来你搬宿舍，收拾东西，才发现它已经过期了。"},{"t":"n","text":"你还是没扔。你把它带回了家，放在书架上。"},{"t":"n","text":"很多年以后，你在她的画室里看见一模一样的一瓶酸奶。"},{"t":"n","text":"她说是给学生的。你们谁都没提那一年。"}],"id":"jiangwan_13"},{"no":14,"title":"报名表","week":36,"bg":"artstudio_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"快递是中午到的。一个纸箱，胶带缠了两圈，寄件人写着她妈妈的名字。"},{"t":"n","text":"箱子里三本教材，一套真题，一张报名表，还有一张便条。"},{"t":"n","text":"便条上写着：妈不逼你，你自己想。"},{"t":"n","text":"便条背面用铅笔抄了一行小字：去年小学美术岗，进面线七十三点五。"},{"t":"n","text":"她把东西一样一样摆在画室的地上，摆得很整齐。"},{"t":"n","text":"报名表是两张，一张填，一张备用。她拿起笔，笔盖咬在嘴里，咬了十分钟。"},{"t":"n","text":"报名费一科七十，三科二百一。她在手机计算器上按了一遍，又按了一遍。"},{"t":"c","id":"jiangwan","text":"二百一。够买两块画布。"},{"t":"n","text":"她把笔从嘴里拿出来，放在表上，没有写。"},{"t":"n","text":"画室的地上还有别的东西：一沓没洗的画笔，半瓶水，一个装饼干的铁盒。"},{"t":"n","text":"铁盒里是她的钱，一卷一卷的，用橡皮筋捆着。"},{"t":"n","text":"她数了一遍，数完把盒子盖上。"},{"t":"c","id":"jiangwan","text":"我算过。考上了，一个月四千多，有寒暑假。可以画画。"},{"t":"n","text":"她说这话的时候在看你，像在等你说「对」。"},{"t":"n","text":"停了很久，她低下头。"},{"t":"c","id":"jiangwan","text":"可是我最近老做一个梦。"},{"t":"n","text":"她说，梦里她考上了，去学校报到，办公室很好，窗明几净。"},{"t":"c","id":"jiangwan","text":"然后我在那儿坐了十年。十年里我一张画也没画。"},{"t":"n","text":"她笑了一下，笑得很难看。"},{"t":"c","id":"jiangwan","text":"醒过来我就想，这个梦也不算是噩梦。它挺安稳的。"},{"t":"n","text":"她把报名表拿起来，对着窗户看。纸很薄，透光。"},{"t":"n","text":"教材的塑封还没拆。三本书摞在一起，书脊上印着「教育教学知识与能力」。"},{"t":"n","text":"她撕开一本，翻了两页，又合上。"},{"t":"c","id":"jiangwan","text":"这书我看不进去。里面讲的都是怎么管小孩。"},{"t":"n","text":"她顿了一下，说：「我小时候，最怕的就是这种老师。」"},{"t":"n","text":"她把书放回箱子，把箱子推到墙角。"},{"t":"c","id":"jiangwan","text":"我妈的字，还是那么难看。"},{"t":"n","text":"她说的是便条上那个「妈」字，最后一笔拖得很长。"},{"t":"c","id":"jiangwan","text":"我怕的不是考不上。我怕的是考上了，就真的不画了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把表填了","hint":"先留一条后路","eff":{"aff":2.0,"stress":-2.0,"familyRel":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你拿过表，说，先填了，考不考到时候再说。"},{"t":"n","text":"她没拦。你把姓名、身份证号、报考科目一项一项填好，字写得比平时工整。"},{"t":"n","text":"填到「报考理由」那一栏，你停住，抬头看她。"},{"t":"n","text":"她说：「写『热爱教育』。」"},{"t":"n","text":"你写了。她看着那四个字，笑了一声，很轻。"},{"t":"c","id":"jiangwan","text":"挺像那么回事的。"},{"t":"n","text":"她把表折好，放进抽屉，和别的东西放在一起。"}]},{"label":"B","text":"陪她把表收起来","hint":"今天不填 · 心情 ↑","eff":{"aff":4.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你把表拿过来，对折，放进抽屉。"},{"t":"n","text":"她看着你的动作，没有阻止。"},{"t":"c","id":"jiangwan","text":"等我想清楚。"},{"t":"n","text":"你说，那就等。"},{"t":"n","text":"她把教材摞起来，压在抽屉上，像压住一样会跑的东西。"},{"t":"n","text":"那张表后来在抽屉里放到了过期。她没有再提。"}]},{"label":"C","text":"问她「如果不用考虑钱，你会怎么选」","hint":"把问题问到底 · 情商 ↑","eff":{"aff":6.0,"eq":3.0,"happy":2.0},"reply":[{"t":"n","text":"你问她，如果不用考虑钱，你会怎么选。"},{"t":"n","text":"她愣住。这个问题她显然没准备。"},{"t":"n","text":"她想得很久。窗外有人在收衣服，衣架碰在一起，叮叮当当。"},{"t":"c","id":"jiangwan","text":"我会画。"},{"t":"n","text":"她说完，又补了一句，声音低下去。"},{"t":"c","id":"jiangwan","text":"但我可能画得不好。"},{"t":"n","text":"你说，那也行。"},{"t":"n","text":"她抬头看你。"},{"t":"c","id":"jiangwan","text":"……什么叫那也行。"},{"t":"n","text":"你说，画得不好也行。你又不是为了画得好才画的。"},{"t":"n","text":"她张了张嘴，没说出话。过了会儿，她低下头，把报名表推到一边。"},{"t":"c","id":"jiangwan","text":"你这个人。"}]}]},{"t":"n","text":"第二天下午，她还是去了画室。表没交，教材也没拆封。"},{"t":"n","text":"她把饼干盒里的钱数出一半，去画材店买了两块画布。"},{"t":"n","text":"回来的时候她抱着画布上楼梯，画布比她宽，拐弯的时候磕了一下墙。"},{"t":"n","text":"她把画布靠在窗边，退后两步看，像在看一个还没开始的什么东西。"}],"id":"jiangwan_14"},{"no":15,"title":"毕业前的画室","week":39,"bg":"artstudio_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"毕业展下周开幕。画室里堆着纸箱，墙上留着一道一道撕胶带的痕。"},{"t":"n","text":"只开了一盏灯，照着最里面那个画架。"},{"t":"n","text":"她背对着门，坐在一张矮凳上。画布上是一片没有画完的海。"},{"t":"n","text":"你站在门口。她没回头。"},{"t":"c","id":"jiangwan","text":"来得正好。你帮我看看，这个蓝色是不是太亮了。"},{"t":"n","text":"你走过去。海是深的，天是灰的，中间那条线还没定下来，蓝压着蓝。"},{"t":"n","text":"画的右下角，有一个很淡的人影，背对镜头，站在天台上。"},{"t":"n","text":"衣角被风吹起来一点。画得很轻，像随时会被海盖过去。"},{"t":"n","text":"那是你。你认出来了。"},{"t":"c","id":"jiangwan","text":"这张画的是你。"},{"t":"n","text":"她说得很平，像在说画里那个人跟她没什么关系。"},{"t":"n","text":"她放下笔，手在裤子上擦了擦。"},{"t":"c","id":"jiangwan","text":"画了三个月。一直画不完。"},{"t":"n","text":"她从凳子上站起来，把位置让给你。"},{"t":"c","id":"jiangwan","text":"你来画最后一笔。"},{"t":"n","text":"她把笔递过来。笔杆是温的。"},{"t":"n","text":"你没有立刻接。你看那张画，看了很久。"},{"t":"n","text":"画的右下角有一行很小的字，凑近才看清：给一个站在天台上的人。"},{"t":"n","text":"她的毕设是另外一张，一米八宽，画的是菜市场。导师说这张太私人，不适合交。"},{"t":"n","text":"她说：「毕设我另画了。这张不交。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"接过笔，画完那一笔","hint":"把画画完 · 关系会变","eff":{"aff":8.0,"happy":6.0,"stress":-4.0,"cre":2.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你接过笔，蘸了一点最浅的蓝。"},{"t":"n","text":"你在海和天之间画了一道很轻的线。手腕没敢用力。"},{"t":"n","text":"海和天，终于分开了。"},{"t":"n","text":"她看了很久，久到灯管发出很轻的一声响。"},{"t":"c","id":"jiangwan","text":"原来要这样。"},{"t":"n","text":"她转过头。灯从侧面照过来，眼睛很亮。"},{"t":"c","id":"jiangwan","text":"你知道吗，我画过很多人。画室的模特、考前班的学生、路上看见的人。"},{"t":"n","text":"她伸手指了指画里那个背影。"},{"t":"c","id":"jiangwan","text":"只画过一次自己。那一次，画里还有你。"},{"t":"n","text":"她说完，低下头，笑了一下。"},{"t":"c","id":"jiangwan","text":"我说这个，是不是太……"},{"t":"n","text":"你说不是。"},{"t":"n","text":"她「嗯」了一声，把笔从你手里拿回去，握了握。"}]},{"label":"B","text":"把笔放下，说「这是你的画」","hint":"不替她完成 · 尊重她","eff":{"aff":3.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你把笔放回她手里。"},{"t":"n","text":"你说，这是你的画。最后一笔应该你自己画。"},{"t":"n","text":"她愣了一下，然后点点头。"},{"t":"c","id":"jiangwan","text":"你说得对。"},{"t":"n","text":"她把笔收回去，握在手里，没有动。"},{"t":"n","text":"那天晚上，她一直没有再动笔。"},{"t":"n","text":"后来那幅画就那样了。海和天之间，留着一条没定下来的边。"}]},{"label":"C","text":"用玩笑岔开","hint":"把话咽回去 · 气氛还在","eff":{"aff":-3.0,"eq":2.0,"happy":-3.0},"reply":[{"t":"n","text":"你说：「我画坏了你可别哭。」"},{"t":"n","text":"她笑了笑，把笔收回去了。"},{"t":"c","id":"jiangwan","text":"行。那就不麻烦你了。"},{"t":"n","text":"她把画布转过去，背对着你，接着画海。"},{"t":"n","text":"你站了一会儿，说你先走了。她说好。"},{"t":"n","text":"后来那幅画一直没画完。再后来，它出现在她的个展上，标签写着「未完成」。"}]}]},{"t":"n","text":"毕业展那天，她的菜市场挂在展厅中间，标签规规矩矩。"},{"t":"n","text":"那张海没有参展。它被卷起来，用报纸包好，靠在画室的墙角。"},{"t":"n","text":"散场以后她回去拿东西，站在那个纸卷前面看了一会儿。"},{"t":"n","text":"她跟考前班签了一年，教素描，一小时四十。她说攒够钱就自己租个地方。"},{"t":"n","text":"她说：「这张我先留着。等我有一面墙。」"},{"t":"n","text":"那面墙，她后来有了。在城北的仓库，在朝北的出租屋，在北京。"},{"t":"n","text":"画一直跟着她。卷着，用报纸包着，胶带换过一次。"},{"t":"n","text":"她说，等挂上去的那天，要挑一个下午。"},{"t":"n","text":"下午的光斜，能照到天台那一角。"},{"t":"block","when":"low","steps":[{"t":"n","text":"你在画室门口站了很久。她背对着你，一直在画。"},{"t":"n","text":"你想说点什么。话到嘴边，变成了一句「很晚了」。"},{"t":"n","text":"她「嗯」了一声，没有回头。"},{"t":"n","text":"你最后什么也没说，轻轻带上了门。"},{"t":"n","text":"门合上之前，你听见笔在画布上的声音，一下，又一下。"}]}],"id":"jiangwan_15"}]},{"id":"ch3","title":"第三章 · 职场","scenes":[{"no":16,"title":"朝北的房间","week":45,"bg":"artstudio_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"她租的房子在城西，老小区，七层，没有电梯。"},{"t":"n","text":"楼道里的墙刷了一半，下半截是绿的，上半截还是白的。声控灯要跺两下脚才亮。"},{"t":"n","text":"门开着一条缝。你推门进去，先看见的是一张画，靠在墙上，一米二宽，画的是菜市场。"},{"t":"n","text":"屋子不大。朝北，窗子对着一堵墙，墙上有别人家的空调外机。"},{"t":"n","text":"她把洗衣机推到角落，上面垫一块木板，当桌子。板子上摊着颜料、笔筒、半包纸巾。"},{"t":"c","id":"jiangwan","text":"朝北的光是平的。画素描正好。"},{"t":"n","text":"她说这话的时候，正在把一管挤空的白色剪开，用刮刀刮里面剩下的。"},{"t":"n","text":"屋里有一张床、一个衣柜、一个电磁炉。冰箱很小，打开只有鸡蛋和一根葱。"},{"t":"n","text":"墙上钉了七个钉子，挂着画、抹布、一把伞。钉子眼周围的墙皮有点掉。"},{"t":"c","id":"jiangwan","text":"房东不让钉。我说我修补。"},{"t":"n","text":"她给你倒水，杯子是买酸奶送的。"},{"t":"n","text":"桌上摊着一张纸，是这个月的账。收入一栏：代课一千二，详情页四百八，墙绘六百。支出一栏：房租一千八，水电一百六，画材三百五。"},{"t":"n","text":"算到最后，差四百。"},{"t":"n","text":"她把笔在纸上点了一下，说：「没事。我少买两管红。」"},{"t":"n","text":"她说得很轻松。轻松得像这个月已经过去了很多次。"},{"t":"n","text":"桌角压着一沓考前班的作业。她昨晚批到两点，每张都写了评语。"},{"t":"n","text":"你翻了翻。有的写着「形不准，重画」，有的写着「这张好，别改了」。"},{"t":"n","text":"有一张画得特别差，她写：「手别抖。多画。」"},{"t":"n","text":"旁边还有一沓打印的图，是淘宝店的详情页，卖保温杯的。"},{"t":"n","text":"她画了六个杯子，摆成不同的角度，配着「温暖一整天」的字。"},{"t":"n","text":"「一张八十。」她说，「画得快的话，一天能画三张。」"},{"t":"n","text":"你问她，画这个难受吗。"},{"t":"n","text":"她想了想，说：「不难受。就是手会懒。」"},{"t":"n","text":"她把那沓详情页翻过来，背面是她的速写，一座桥，桥上没有人。"},{"t":"n","text":"她说：「我都是正面画杯子，背面画自己的。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把灯换成两根灯管","hint":"让光好一点 · 好感 ↑","eff":{"aff":4.0,"happy":2.0,"fin":-2.0},"reply":[{"t":"n","text":"你去楼下五金店买了两根灯管，一根暖光，一根白光。"},{"t":"n","text":"她扶着梯子。你拧螺丝的时候，她在下面说：「左边一点。再左边。」"},{"t":"n","text":"两根都亮起来的时候，屋里白得有点不真实。"},{"t":"n","text":"她站在画前面，看了很久，说：「原来这个颜色是这样的。」"}]},{"label":"B","text":"陪她算这个月的账","hint":"把数字摊开 · 情商 ↑","eff":{"aff":5.0,"eq":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你把纸拉过来，一项一项跟她对。"},{"t":"n","text":"算到画材那栏，她说三百五是最低的，画大画要五百。"},{"t":"n","text":"你说，那就把墙绘的价提上去。她愣了一下，说：「提多少。」"},{"t":"n","text":"你说，一面墙两天，加上材料，至少八百。"},{"t":"n","text":"她低头，在纸上写了一个八百，又划掉，写了一个七百五。"}]},{"label":"C","text":"给她介绍一个活","hint":"帮她接一单 · 财力 ↑","eff":{"aff":3.0,"fin":2.0,"happy":1.0},"reply":[{"t":"n","text":"你想起朋友开的咖啡馆要画一块黑板，问她接不接。"},{"t":"n","text":"她问：「多大？画什么？什么时候要？」"},{"t":"n","text":"你一一答了。她点头，说：「行。三百。」"},{"t":"n","text":"交稿那天，她把黑板擦得干干净净，画了一整面咖啡豆和云。"},{"t":"n","text":"她收钱的时候说：「原来被人介绍活是这种感觉。」"}]}]},{"t":"n","text":"晚上她送你下楼。路灯坏了一盏，楼下的花坛黑着。"},{"t":"n","text":"她穿着拖鞋，站在台阶上，抱着胳膊。"},{"t":"c","id":"jiangwan","text":"这里晚上很黑。"},{"t":"n","text":"她抬头，看了一会儿天。"},{"t":"c","id":"jiangwan","text":"但星星比学校多。可能是因为楼层高。"},{"t":"n","text":"你说明明是因为这边灯少。"},{"t":"n","text":"她说：「你就不能浪漫一点。」"},{"t":"n","text":"说完自己笑了，转身回去。楼道一层一层亮起来。"},{"t":"n","text":"你走到小区门口，回头看。七楼那扇窗亮着，光是黄的。"},{"t":"n","text":"她大概又开始画了。夜里画丙烯，干得快，味道小。"},{"t":"n","text":"你站了一会儿，才走。"}],"id":"jiangwan_16"},{"no":17,"title":"改到第五稿","week":48,"bg":"library_day","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"书店在一条老街上，两间门面，里面有一面四米宽的白墙，空着。"},{"t":"n","text":"店长三十来岁，戴眼镜，说话很快。他要「文艺一点，但要好拍照」。"},{"t":"n","text":"她画的第一稿是梧桐和旧书架，灰绿的，光是斜的。"},{"t":"n","text":"店长看了，说：「挺好。就是有点闷。能不能再亮一点？」"},{"t":"n","text":"第二稿，她把颜色提亮，加了两只猫。"},{"t":"n","text":"店长说：「猫很好。能不能再 ins 一点？」"},{"t":"n","text":"第三稿，她加了绿植、咖啡杯、一句英文。"},{"t":"n","text":"店长说：「英文换成中文吧，我们是中国书店。」"},{"t":"n","text":"第四稿，她把英文换成了「读书是回家的路」。"},{"t":"n","text":"店长看了很久，说：「字能不能再大一点？门口路过的人得看见。」"},{"t":"n","text":"现在是第五稿。晚上十点，她站在那面墙前面，手里拿着一支笔，笔尖悬着。"},{"t":"n","text":"她的右手腕贴着一块膏药，边缘翘起来了。"},{"t":"c","id":"jiangwan","text":"他说再亮一点，我就再亮一点。他说字大一点，我就再大一点。"},{"t":"n","text":"她把笔放下。"},{"t":"c","id":"jiangwan","text":"我不是不能改。我是怕改着改着，就不知道自己原来想画什么了。"},{"t":"n","text":"墙上现在是第五稿的草稿：梧桐退到最后面，前面是绿植、咖啡杯、一行很大的字。"},{"t":"n","text":"原来那点斜进来的光，没有了。"},{"t":"n","text":"她把手机递给你，屏幕上是店长的消息，一共十七条。"},{"t":"n","text":"最后一条是：「姐，明天能好吗？我们周末要开业。」"},{"t":"n","text":"她把手机拿回去，锁屏，放在桌上。"},{"t":"c","id":"jiangwan","text":"开业。多大事。"},{"t":"n","text":"她说完就笑了一下，笑得有点疲惫。"},{"t":"n","text":"桌上摊着合同，两页纸，边角卷了。上面写着：壁画一面，三千二，含材料。"},{"t":"n","text":"她算给你听：材料八百，搭架子两百，请人帮忙三百，剩下不到两千。"},{"t":"n","text":"「五稿。」她说，「一稿四百块。」"},{"t":"n","text":"她把合同翻过来，在背面空白处画了一个很小的窗。"},{"t":"n","text":"窗里有一束光，光的颜色是橘的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把话说清楚","hint":"替她谈一次 · 情商 ↑","eff":{"aff":5.0,"eq":2.0,"happy":3.0,"fin":1.0},"reply":[{"t":"n","text":"第二天你陪她去见店长。你把她的第一稿摊在桌上，说：「她想要的是这个。」"},{"t":"n","text":"店长看了很久，问：「这个能拍照吗？」"},{"t":"n","text":"她说：「你试试。」"},{"t":"n","text":"店长把手机举起来，对着第一稿的打印件拍了一张，看了看，说：「行吧。你们搞艺术的。」"},{"t":"n","text":"最后那面墙用的是第一稿的构图，只把颜色提亮了一点。"},{"t":"n","text":"她画完那天，站在墙前面，看了很久，说：「谢谢。」"}]},{"label":"B","text":"陪她改到第五稿","hint":"先把活干完 · 压力 ↑","eff":{"aff":3.0,"stress":2.0,"fin":3.0,"happy":-1.0},"reply":[{"t":"n","text":"你留下来帮她调颜色。白加一点黄，再加一点绿。"},{"t":"n","text":"凌晨两点，第五稿画完了。字很大，从门口就能看见。"},{"t":"n","text":"店长第二天来验，很满意，当场转了钱。"},{"t":"n","text":"她收了钱，说了谢谢，等人走了，把手机里存的墙面照片删了。"},{"t":"n","text":"你问她为什么删。她说：「留着也没用。」"}]},{"label":"C","text":"说「不接也行」","hint":"给她退路 · 心情 ↑","eff":{"aff":2.0,"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你说，不接也行。违约金我陪你出。"},{"t":"n","text":"她愣了一下，然后笑了。"},{"t":"c","id":"jiangwan","text":"房租不答应。"},{"t":"n","text":"她拿起笔，接着画。"},{"t":"n","text":"但那天晚上，她把这句话记在了速写本的第一页。"}]}]},{"t":"n","text":"一周后，钱到账。她请你去吃火锅，点了三盘肉。"},{"t":"n","text":"锅开的时候，她把肉全下进去，说：「今天我请，别客气。」"},{"t":"n","text":"吃到一半，她忽然放下筷子。"},{"t":"c","id":"jiangwan","text":"我下个月想画一张自己的画。不接活，不给人看，就画。"},{"t":"n","text":"你问，画什么。"},{"t":"n","text":"她说：「还不知道。先空一块画布出来。」"},{"t":"n","text":"那天晚上她喝了三杯酸梅汤，脸有点红。走出火锅店的时候，她说：「我好久没这么饱了。」"},{"t":"n","text":"街上风很凉。她把外套的拉链拉到最上面，走了一段，忽然说：「谢谢你今天陪我。」"},{"t":"n","text":"你说，谢什么。"},{"t":"n","text":"她说：「谢你没让我一个人改到第五稿。」"},{"t":"n","text":"说完她自己愣了一下，好像觉得这句话太软了。"},{"t":"c","id":"jiangwan","text":"……走了。明天还要画。"},{"t":"n","text":"她走在前面，走得很快。路灯把影子拉长，又缩短。"}],"id":"jiangwan_17"},{"no":18,"title":"个展","week":51,"bg":"auditorium","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"美术馆在旧厂房区，红砖墙，铁门上的漆掉了一半，露出底下的锈。"},{"t":"n","text":"展厅在二楼，要爬一段很陡的水泥楼梯。楼梯转角贴着一张手写的纸：江晚个展，二楼。"},{"t":"n","text":"展厅不大，两百来平，屋顶很高，灯是从钢架上吊下来的。"},{"t":"n","text":"一共二十四张画。小的巴掌大，大的那几张要两个人抬。"},{"t":"n","text":"来的人不多。有几个是考前班的学生，有几个是美院的同学，还有几个是路过进来的。"},{"t":"n","text":"每一幅画前面都有人站着。有人站得久，有人站两分钟就走。"},{"t":"n","text":"她站在最里面那幅画旁边，穿一件白衬衫，袖口和下摆都沾了颜料。"},{"t":"n","text":"衬衫是新的。她大概只在今天穿过一次。"},{"t":"n","text":"她手里端着一个塑料杯，里面是很便宜的汽水，气已经跑了一半。"},{"t":"c","id":"jiangwan","text":"你来了。"},{"t":"n","text":"她把杯子递给你，又从旁边的纸箱里拿了一个新的，倒上。"},{"t":"c","id":"jiangwan","text":"随便看。别客气。今天的东西都不卖。"},{"t":"n","text":"你沿着墙走了一圈。第一张是菜市场，第二张是梧桐，第三张是一扇窗。"},{"t":"n","text":"天台的系列挂在中间，三张一排，跟高中走廊那次一样的排法。"},{"t":"n","text":"这次它们挂在最好的位置，灯也调过，光是暖的。"},{"t":"n","text":"有个女生在那三张前面站了很久，掏出本子记了什么。"},{"t":"n","text":"最里面，靠墙，单独隔出一块地方。那幅画比别的都大。"},{"t":"n","text":"画的是一个人，背对镜头，站在天台上，衣角被风吹起来一点。"},{"t":"n","text":"是你。"},{"t":"n","text":"标签是手写的，白卡片，黑笔：不卖。"},{"t":"n","text":"你站在那幅画前面。她走过来，站在你旁边，两个人一起看。"},{"t":"c","id":"jiangwan","text":"这张画了三个月。后来一直没动。"},{"t":"n","text":"她喝了一口汽水。"},{"t":"c","id":"jiangwan","text":"展览的名字，本来想叫『天台』。后来觉得太窄了。现在叫『留一会儿』。"},{"t":"n","text":"你问她，为什么叫这个。"},{"t":"c","id":"jiangwan","text":"因为来看的人，最多留三分钟。"},{"t":"n","text":"她笑了一下，接着说：「三分钟也好。总比没有强。」"},{"t":"n","text":"过了一会儿，她开口，语气很平常。"},{"t":"c","id":"jiangwan","text":"我下个月去北京。有个工作室，租金很贵，但窗户朝南。"},{"t":"n","text":"她顿了一下。"},{"t":"c","id":"jiangwan","text":"朝南的话，冬天下午的光能进来。可以画到五点。"},{"t":"n","text":"她说的是光，不是别的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我跟你一起去」","hint":"把话说出口 · 关系会变","eff":{"aff":8.0,"happy":6.0,"stress":-2.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你说，我跟你一起去。"},{"t":"n","text":"她愣住了。杯子差点没拿稳，汽水洒出来一点，滴在鞋面上。"},{"t":"c","id":"jiangwan","text":"你想清楚了？北京很干，颜料也贵。"},{"t":"n","text":"你说想清楚了。"},{"t":"n","text":"她低下头，看着自己的鞋尖，看了很久。"},{"t":"c","id":"jiangwan","text":"我那儿只有一间房。窗户是朝南的，但是很小。"},{"t":"n","text":"你说，一张画布放得下就行。"},{"t":"n","text":"她笑了。笑着笑着，眼睛红了，抬手用手背擦了一下。"},{"t":"c","id":"jiangwan","text":"那我把画室钥匙给你一把。别弄丢。"}]},{"label":"B","text":"说「祝你成功」","hint":"把话留在原地","eff":{"aff":2.0,"happy":-4.0,"stress":3.0},"reply":[{"t":"n","text":"你说，祝你成功。"},{"t":"n","text":"她点点头，说：「谢谢。」"},{"t":"n","text":"然后她转身去招呼别的客人。你站在那幅画前面，站了很久。"},{"t":"n","text":"有一个瞬间，她好像要回头，但是没有。"}]},{"label":"C","text":"问她「那幅画，为什么不卖」","hint":"问那句没问的 · 情商 ↑","eff":{"aff":4.0,"eq":3.0,"happy":-1.0},"reply":[{"t":"n","text":"你指着标签问她，为什么写「不卖」。"},{"t":"n","text":"她看着画，说：「因为差一笔。」"},{"t":"n","text":"「差谁的一笔？」你问。"},{"t":"n","text":"她没有回答。她把杯子里的汽水喝完，捏扁，扔进垃圾桶。"},{"t":"c","id":"jiangwan","text":"差的那一笔，我自己也画不出来。"}]}]},{"t":"n","text":"门口有个人站了一会儿，没进来。"},{"t":"n","text":"一个五十来岁的女人，深红色外套，头发梳得整齐，手里拎着一个保温桶。"},{"t":"n","text":"她在门口站了大概一分钟，才迈进来。"},{"t":"n","text":"江晚看见她，愣了一下。"},{"t":"c","id":"jiangwan","text":"妈。"},{"t":"n","text":"她妈妈「嗯」了一声，说你忙你的，我看看。"},{"t":"n","text":"然后她一幅一幅看。看得很慢，在每幅画前面都停。"},{"t":"n","text":"她在菜市场那张前面站得最久。那张画的是早市，塑料棚，地上的水，一堆卖剩的青菜。"},{"t":"n","text":"她妈妈看了很久，说：「这个棚子，像你姥姥家那边那个。」"},{"t":"n","text":"看完一圈，她走到江晚面前。"},{"t":"c","id":"jiangwan","text":"你怎么来了。"},{"t":"n","text":"她妈妈说：「你爸让我来的。他说，闺女第一次办展，不去不像话。」"},{"t":"n","text":"她顿了顿，环视了一圈这间厂房改的展厅。"},{"t":"n","text":"「这墙刷得不行。」她说，「都起皮了。」"},{"t":"n","text":"江晚笑了，笑得有点抖。"},{"t":"n","text":"她妈妈把保温桶放在桌上，打开。里面是排骨汤，还热着。"},{"t":"n","text":"「喝点。」她说，「你看你瘦的。」"},{"t":"n","text":"散场的时候，她妈妈帮着收杯子，把塑料杯一个一个摞起来，摞得很整齐。"},{"t":"n","text":"你的手机在口袋里震。是家里。"},{"t":"n","text":"你走到楼梯间接。信号不好，说了三遍「喂」。"},{"t":"n","text":"妈妈说，你爸血压有点高，住了两天院，已经没事了。"},{"t":"n","text":"你说，我明天回去。她说，不用，你忙你的。"},{"t":"n","text":"挂了电话，你在楼梯上坐了一会儿，才回展厅。"},{"t":"n","text":"十点，人走光了。她把展厅的灯一盏一盏关掉。"},{"t":"n","text":"最后只剩最里面那一盏，照着那幅画。"},{"t":"n","text":"她站在画前面，抱着胳膊，看了很久。"},{"t":"c","id":"jiangwan","text":"你说，这个蓝是不是太亮了。"},{"t":"n","text":"你走过去。画里的天，比这间屋子里的任何东西都要亮。"},{"t":"n","text":"你说，是亮了一点。"},{"t":"n","text":"她「嗯」了一声，没有再改。"}],"id":"jiangwan_18"},{"no":19,"title":"房东要卖房","week":54,"bg":"artstudio_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"房东在门上贴了一张纸：房屋出售，月底前腾空。"},{"t":"n","text":"纸是用胶带贴的，四个角都翘着，像已经贴了很久。"},{"t":"n","text":"她在楼下打电话。手机夹在肩膀和耳朵之间，手里拿着一个卷尺。"},{"t":"c","id":"jiangwan","text":"……对，要能画画。能钉钉子吗？……不能啊。好，谢谢。"},{"t":"n","text":"她挂了电话，把号码划掉。纸上已经划掉了十一个。"},{"t":"n","text":"她抬头看见你，说：「房东要卖房。说给我十天。」"},{"t":"n","text":"十天后是月底。她的画有二十三张，加上画架、画布、颜料、一张床、一个衣柜。"},{"t":"n","text":"最大的那张一米八宽，是菜市场。电梯进不去。"},{"t":"n","text":"她量了一下楼梯的宽度，又量了一下画的对角线。"},{"t":"c","id":"jiangwan","text":"斜着抬。六楼。"},{"t":"n","text":"那天下午下起了雨。雨不大，但很密。"},{"t":"n","text":"她翻出一卷塑料布，把画一层一层裹起来。裹到第三层，胶带用完了。"},{"t":"n","text":"她用绳子捆，绳子在画框上勒出一道印。"},{"t":"n","text":"抬到三楼的时候，她的手腕抖了一下。画磕在墙上，塑料布破了一个口。"},{"t":"n","text":"她停下来，隔着塑料布摸了摸那个位置，说：「没事。画布厚。」"},{"t":"n","text":"搬到楼下，她的头发全湿了，白衬衫贴在背上。"},{"t":"n","text":"她站在雨里，看着堆在单元门口的一堆东西，忽然笑了一下。"},{"t":"c","id":"jiangwan","text":"你看，我全部的家当。"},{"t":"n","text":"画、画架、一箱颜料、一个电磁炉、一床被子。摆在雨里，像在搬家，也像在摆摊。"},{"t":"n","text":"她一边等车一边打电话。这次是打给一个中介。"},{"t":"c","id":"jiangwan","text":"仓库改的工作室，合租，九百……能钉钉子吗？……能啊。那行。"},{"t":"n","text":"她挂了电话，把地址记在手上，用圆珠笔，写在手背。"},{"t":"n","text":"雨把字洇开了一点。她低头看了看，又描了一遍。"},{"t":"n","text":"货车来的时候，司机绕着那堆东西走了一圈，说：「这么多画？」"},{"t":"n","text":"她说：「不多。还有一半在学校的储藏室。」"},{"t":"n","text":"司机问：「画画的？」"},{"t":"n","text":"她说：「嗯。」"},{"t":"n","text":"司机说：「这个不赚钱吧。」"},{"t":"n","text":"她把绳子在手上绕了两圈，说：「看怎么算。」"},{"t":"n","text":"车斗里没有棚布。她跟司机一起把画靠边放好，用身体挡着。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她把画搬走","hint":"先把画安顿好 · 好感 ↑","eff":{"aff":6.0,"str":2.0,"happy":2.0},"reply":[{"t":"n","text":"你叫了一辆货车。司机看了看那堆东西，说要加钱。"},{"t":"n","text":"她掏钱的时候手在抖，你按住她的手，把钱付了。"},{"t":"n","text":"新地方是城北一个仓库改的工作室，跟另外两个人合租，一个月九百。"},{"t":"n","text":"墙是水泥的，可以钉钉子。她进去第一件事，是把最大的那张画靠墙立好。"}]},{"label":"B","text":"让她先把画寄存在你那儿","hint":"腾一个地方 · 心情 ↑","eff":{"aff":5.0,"happy":3.0,"stress":-3.0},"reply":[{"t":"n","text":"你说，画先放我那儿。等你找到地方再搬。"},{"t":"n","text":"她犹豫了一下，问：「你那儿潮吗？」"},{"t":"n","text":"你说不潮。她说：「那张不卖的，你别弄脏。」"},{"t":"n","text":"那天晚上，那张画立在你房间的墙角，用塑料布裹着，像一个不说话的人。"}]},{"label":"C","text":"说「要不别租工作室了」","hint":"说句现实的话 · 压力 ↓","eff":{"aff":1.0,"stress":-2.0,"happy":-2.0},"reply":[{"t":"n","text":"你说，要不别租工作室了。在家里画也一样。"},{"t":"n","text":"她把绳子打了个结，抬头看你。"},{"t":"c","id":"jiangwan","text":"在家里画，颜料味散不掉。房东会来说。"},{"t":"n","text":"她顿了一下。"},{"t":"c","id":"jiangwan","text":"那我画什么。"},{"t":"n","text":"你没答上来。她低下头，继续捆。"}]}]},{"t":"n","text":"最后一张画抬上车的时候，天已经黑了。雨还在下。"},{"t":"n","text":"她用塑料布把画裹了三层，自己淋着，站在车斗边上，一只手扶着画。"},{"t":"n","text":"车开走的时候，她回头看那栋楼。七楼那扇窗黑着。"},{"t":"n","text":"她说：「我在那儿住了三年。」"},{"t":"n","text":"然后她抹了一把脸上的水，说：「走吧。新的地方有热水。」"},{"t":"n","text":"新的地方确实有热水，但水压不稳，洗到一半会变凉。"},{"t":"n","text":"她站在水池边试了试，说：「行。比没有强。」"},{"t":"n","text":"那天晚上她把画一张一张立好，靠着墙，像一排人站在那里。"},{"t":"n","text":"她退后几步看，说：「这样看，还挺多的。」"},{"t":"n","text":"你说明明只有二十三张。她说：「二十三也是多。」"}],"id":"jiangwan_19"},{"no":20,"title":"去北京的车票","week":57,"bg":"artstudio_night","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"城北的工作室在仓库二楼，很大，很空，冬天冷得握不住笔。"},{"t":"n","text":"她的东西只占了四分之一。剩下的地方，另外两个人堆着纸箱和旧家具。"},{"t":"n","text":"窗子在北面，很高，光从上面斜下来，照在水泥地上，一块一块。"},{"t":"n","text":"她坐在这块光里，脚边放着一个行李箱，已经合上了，拉链上挂着一个牌子。"},{"t":"n","text":"牌子上是北京的字，写着工作室的地址。"},{"t":"n","text":"桌上摊着一叠纸：租房合同、车票、一张手写的清单。"},{"t":"n","text":"清单上写着：画布六张，颜料一箱，笔两筒，速写本四本，锅一个。"},{"t":"c","id":"jiangwan","text":"锅是新的。那边的房租不含厨房。"},{"t":"n","text":"她把清单折起来，放进行李箱侧袋，又拿出来，看了看，再放回去。"},{"t":"n","text":"你坐在她对面的木箱上。屋里很静，能听见楼下有人在搬东西。"},{"t":"c","id":"jiangwan","text":"一年。合同签一年。"},{"t":"n","text":"她抬头。"},{"t":"c","id":"jiangwan","text":"一年以后，不知道。可能回来，可能不回来。"},{"t":"n","text":"她说这话的时候很平静，像在报告天气。"},{"t":"n","text":"你问她，怕不怕。"},{"t":"n","text":"她想了想。"},{"t":"c","id":"jiangwan","text":"怕。北京那么大，我连地铁都不会坐。"},{"t":"n","text":"她低头笑了一下。"},{"t":"c","id":"jiangwan","text":"但我更怕留在这儿，画一辈子墙绘。"},{"t":"n","text":"她伸手，把桌上的车票推到你面前。下周三，早上八点二十。"},{"t":"c","id":"jiangwan","text":"我不是来告别的。我是想让你知道，我走了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「北京我也能去」","hint":"把这边放下 · 关系会变","eff":{"aff":8.0,"happy":6.0,"stress":2.0,"lover":true},"reply":[{"t":"n","text":"你说，北京我也能去。这边的活可以辞。"},{"t":"n","text":"她看着你，看了很久。"},{"t":"c","id":"jiangwan","text":"你的工作呢。你妈呢。"},{"t":"n","text":"你说，慢慢来。"},{"t":"n","text":"她低下头，手指在车票的边上摩挲。"},{"t":"c","id":"jiangwan","text":"你别因为我去。你要是因为我去，以后有一天你后悔了，我不知道怎么办。"},{"t":"n","text":"你说，不是因为你去。是因为我想跟你一起看看那个窗户朝南的房子。"},{"t":"n","text":"她抬起头，眼睛里有水光，但没有掉下来。"},{"t":"c","id":"jiangwan","text":"那你要自己找房子。我那儿只有一张床。"}]},{"label":"B","text":"说「这边还有事。你先去」","hint":"不拦她 · 各自往前","eff":{"aff":4.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你说，这边还有事。你先去。"},{"t":"n","text":"她点点头，把车票收回去。"},{"t":"c","id":"jiangwan","text":"嗯。我也是这么想的。"},{"t":"n","text":"她把车票放进口袋，按了按。"},{"t":"c","id":"jiangwan","text":"那……就到这儿？"},{"t":"n","text":"你说，到这儿。"},{"t":"n","text":"她站起来，走到窗边，背对着你。"},{"t":"c","id":"jiangwan","text":"你走的时候把门带上。钥匙放在门框上。"}]},{"label":"C","text":"说「画展我帮你看。你安心画」","hint":"留在画外 · 更长久","eff":{"aff":5.0,"happy":3.0,"eq":2.0},"reply":[{"t":"n","text":"你说，你安心画。这边要有什么展、什么手续，我帮你看。"},{"t":"n","text":"她愣了一下，然后笑起来，笑得比刚才轻松。"},{"t":"c","id":"jiangwan","text":"你还真把自己当策展人了。"},{"t":"n","text":"你说，不行吗。"},{"t":"n","text":"她说：「行。那你要认真看。别光说好看。」"},{"t":"n","text":"她从抽屉里翻出一把钥匙，放在桌上。"},{"t":"c","id":"jiangwan","text":"这把给你。帮我看着点。别让画受潮。"}]}]},{"t":"n","text":"周三早上，站台。人很多，箱子轮子在地上滚，声音很杂。"},{"t":"n","text":"她穿那件灰绿衬衫，背一个帆布袋，手里拎着行李箱。风把她的头发吹到脸上。"},{"t":"n","text":"检票口开了。她走进去，回头，冲你抬了抬下巴。"},{"t":"n","text":"她说了句什么，隔着玻璃，听不清。"},{"t":"n","text":"车开动的时候，她的位置从窗边挪到中间，很快就找不到了。"},{"t":"n","text":"你站在站台上，等到那趟车看不见。铁轨很亮，一直伸到远处。"},{"t":"n","text":"回程的公交车上，你坐在最后一排。窗外的城市一段一段往后退。"},{"t":"n","text":"你想起高三那年，她说过「画不会跑，手会」。"},{"t":"n","text":"现在她的手在另一座城市，画着另一面墙。"},{"t":"n","text":"你掏出手机，看见她发来一条消息，是三个字：到了。"},{"t":"n","text":"你回了一个「好」。"},{"t":"n","text":"过了两分钟，她又发来一条：「窗户真的是朝南的。」"}],"id":"jiangwan_20","judgeAfter":true}]},{"id":"finale","title":"终章 · 三结局","scenes":[{"no":21,"title":"把时间画下来","week":60,"bg":"artstudio_seaside","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"你们搬去了海边。房子是租的，墙皮有点掉，但窗户很大。"},{"t":"n","text":"下午的光从窗户进来，能铺满整张画布。她算过，从两点到五点，正好三个小时。"},{"t":"n","text":"她画画，你工作。你下班回来，她常常还在画，桌上放着凉了的饭。"},{"t":"n","text":"她听见门响，会说一句「回来了」，眼睛不离开画布。"},{"t":"n","text":"你帮她洗笔。水很快变蓝，一层一层往下沉，跟很多年前那个画室的洗笔筒一样。"},{"t":"n","text":"她给你讲今天的光是什么颜色。今天是灰蓝，加了一点赭石。"},{"t":"n","text":"她的画开始有人买了。不多，但够交房租，够买颜料，够在冬天开暖气。"},{"t":"n","text":"有一次她卖出去一张大的，回来在门口站了一会儿，说：「我有点舍不得。」"},{"t":"n","text":"第二天她又说：「卖了好。卖了才能画下一张。」"},{"t":"n","text":"她妈妈来过一次。坐了两个小时的车，拎着一个保温桶，还有一箱橘子。"},{"t":"n","text":"进门先看墙，说：「这墙刷得不行。」"},{"t":"n","text":"第二天她借了滚筒和涂料，把那面墙刷了两遍。刷完站在门口看，说：「行了。」"},{"t":"n","text":"那张没画完的海挂在客厅。她一直没有补最后一笔。"},{"t":"n","text":"你问过一次。她说：「补了就不是那天了。」"},{"t":"n","text":"有一次你问她：「你后悔吗？没去考编。」"},{"t":"n","text":"她想了想。"},{"t":"c","id":"jiangwan","text":"后悔过。"},{"t":"n","text":"她把画笔在洗笔筒里搅了搅。"},{"t":"c","id":"jiangwan","text":"去年冬天特别冷，颜料冻住过一次。那天我确实后悔。"},{"t":"n","text":"她抬起头，看窗外。"},{"t":"c","id":"jiangwan","text":"但每天早上醒来，看见海，就不后悔了。"},{"t":"n","text":"她顿了顿。"},{"t":"c","id":"jiangwan","text":"而且你在。"},{"t":"n","text":"她说完，低头继续画。笔在画布上走，很轻。"},{"t":"n","text":"窗外，海是灰的，天边有一点点橘。下午四点的那种橘。"},{"t":"n","text":"她每天六点起，画到中午。下午带两个学生，一个七岁，一个十岁，在楼下的空房间里。"},{"t":"n","text":"十岁的那个坐不住，画两笔就要站起来。她说：「让他站。站着也能画。」"},{"t":"n","text":"七岁的那个画得很好，好得有点不像小孩。她反而担心，跟她妈妈说：「让她多玩玩。」"},{"t":"n","text":"空房间的墙是白的。孩子们在上面画，她不让擦。"},{"t":"n","text":"两面墙，画满了太阳、恐龙、一艘翻过来的船。"},{"t":"n","text":"你们的墙也不让钉太多钉子。房东来看过一次，说：「钉可以，别钉太多。」"},{"t":"n","text":"她说好。等他走了，又钉了一个。"},{"t":"n","text":"冬天的颜料会冻。她用一个热水袋焐着，画一会儿，把颜料盒挪到暖气边上。"},{"t":"n","text":"有一次卖出去一张画，买家说，能不能再画一张一样的。"},{"t":"n","text":"她说不画。"},{"t":"n","text":"买家说加钱。她还是说不画。"},{"t":"n","text":"那天晚上她有点不安，问你：「我是不是太犟了。」"},{"t":"n","text":"你说，是有一点。"},{"t":"n","text":"她笑了，说：「那就好。」"},{"t":"n","text":"她妈妈打过一次电话，说她爸在手机上看了她的画，看了很久，没说好，也没说不好。"},{"t":"n","text":"挂电话之前，她妈妈说：「你爸让我问你，冬天冷不冷。」"},{"t":"n","text":"她说，不冷，有暖气。"},{"t":"n","text":"你们吵过一次架，为了一顿饭。"},{"t":"n","text":"那天你加班到九点，回来看见桌上摆着饭，已经凉了。她在画室里，门关着。"},{"t":"n","text":"你敲门，她出来，手上全是蓝。"},{"t":"c","id":"jiangwan","text":"我忘了时间。"},{"t":"n","text":"你说，饭凉了。"},{"t":"n","text":"她说，热一下就行。"},{"t":"n","text":"两个人都没有大声。但那天晚上，谁也没先睡。"},{"t":"n","text":"后来她出来了，坐在床边，说：「我画画的时候，真的听不见。」"},{"t":"n","text":"你说，我知道。"},{"t":"c","id":"jiangwan","text":"可是你不能一直知道。"},{"t":"n","text":"你说，那我们定个规矩。画到六点，你敲一下墙。"},{"t":"n","text":"她想了想，说：「敲两下。一下我听不见。」"},{"t":"n","text":"后来你们真的敲墙。一下是吃饭，两下是她听见了。"},{"t":"n","text":"再后来，那面墙上多了一排很小的颜料点，是敲的时候蹭上去的。"}],"quality":{"high":["你们的日子不富裕，但每天都有新的颜色。她画她的海，你忙你的事，晚上一起吃一顿热饭。","你觉得这样很好。她也是。"],"mid":["她画她的，你忙你的。你们很少吵架，也很少深谈。","但晚上关灯前，她会跟你说一句「今天画得不错」。你说「你也是」。"],"low":["她的画越卖越贵，越来越忙。你已经很久没有和她一起看过黄昏了。","那张没画完的海还挂在客厅。有一天你发现，画上落了一层很薄的灰。"]},"id":"jiangwan_21","ending":"stay","endingName":"结局一 · 把时间画下来"},{"no":22,"title":"有些颜色，一个人看也算数（爱过 / 错过）","week":60,"bg":"auditorium","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"她去了北京。"},{"t":"n","text":"走之前，她把那幅「不卖」的画留给了你。用报纸包着，外面缠了三层胶带。"},{"t":"n","text":"她说：「你先帮我放着。等我那边有墙了，我再来拿。」"},{"t":"n","text":"她一直没有来拿。"},{"t":"n","text":"第一年，她常发照片：工作室、窗外的树、画到一半的画布。"},{"t":"n","text":"照片里的房间很小，一张床，一张桌子，一个画架，窗户朝南。"},{"t":"n","text":"有一次她发来一张，窗台上放着一盆绿萝，旁边是那管用剩的赭石。"},{"t":"n","text":"配的字是：「这个颜色还是最便宜。」"},{"t":"n","text":"后来照片少了。再后来，只有朋友圈的展览海报。"},{"t":"n","text":"你在海报上看见她的名字，排得很前。"},{"t":"n","text":"你没有点赞。你点开，放大，看她的名字，看了很久，然后关掉。"},{"t":"n","text":"很多年后，你出差去北京。她的个展在同一周。"},{"t":"n","text":"你住的酒店离展厅两站地铁。"},{"t":"n","text":"你把手机扣在桌上，没有去。"},{"t":"n","text":"回酒店的路上，你路过一家画材店。橱窗里摆着一管赭石，跟她当年给你的一模一样。"},{"t":"n","text":"你进去买了一管。店员问你要不要包装，你说不用。"},{"t":"n","text":"回家以后，你把它放在那幅画的下面，没有打开。"},{"t":"n","text":"后来你搬了两次家。那幅画一直挂着，那管颜料一直在画下面。"},{"t":"n","text":"又过了几年，你在新闻上看见她的名字。一个很大的奖，照片里她站在一幅画前面。"},{"t":"n","text":"画的是海。右下角有一个很小的人影。"},{"t":"n","text":"你把那张新闻截了图，存进一个很久没打开的相册。"},{"t":"n","text":"相册的名字是「2016」。"}],"quality":{"high":["你后来有了自己的生活。你只是偶尔会想，如果当时跟她走了，会怎么样。","想完，你继续过你的日子。这不叫遗憾，这叫记得。"],"mid":["她的画展你收过几张海报，夹在一本画册里。","你没有再去过现场。她也没有再问。"],"low":["你把那幅画挂在客厅。有一天你发现，画里那个背影，已经看不太清了。","你没有去修。你只是把灯调亮了一点。"]},"id":"jiangwan_22","ending":"miss","endingName":"结局二 · 有些颜色，一个人看也算数（爱过 / 错过）"},{"no":23,"title":"画外的朋友","week":60,"bg":"auditorium","cast":["jiangwan"],"steps":[{"t":"cast","list":["jiangwan"],"focus":"jiangwan"},{"t":"n","text":"你成了她的第一个观众。"},{"t":"n","text":"后来，也成了她所有展览的策展人。"},{"t":"n","text":"她每画完一幅，都会先给你看。画布上的颜料还没干，屋子里全是味道。"},{"t":"n","text":"你说好看，她就说：「你懂什么。」"},{"t":"n","text":"你说不好看，她就说：「你终于说实话了。」"},{"t":"n","text":"然后她会把画转过去，自己看很久，第二天改，或者不改。"},{"t":"n","text":"你帮她写展签。她嫌你写得文绉绉，自己拿过去改，改成很短的句子。"},{"t":"n","text":"「一个女人在等公交。」「下午四点的窗。」「我爸的自行车。」"},{"t":"n","text":"她给你画过一张肖像。画里的你，比你自己好看。"},{"t":"n","text":"你问她：「为什么不签名？」"},{"t":"n","text":"她说：「这张不卖，签什么名。」"},{"t":"n","text":"那张画挂在你家的走廊。来的人问是谁画的，你说是一个朋友。"},{"t":"n","text":"你们一辈子都是朋友。"},{"t":"n","text":"她结婚的时候，你坐在第一排，帮她抱着画筒。"},{"t":"n","text":"画筒里是她要送给对方的画，卷得很紧，外面裹着牛皮纸。"},{"t":"n","text":"仪式开始前，她从后台探出头，问你：「画筒呢？」"},{"t":"n","text":"你举了举。她说：「别弄皱了。」"},{"t":"n","text":"婚礼上她说誓词，说到一半哭了，妆花了一点。你在下面鼓掌，鼓得很用力。"},{"t":"n","text":"后来她开了自己的画室。有个三岁的小学员，在墙上画画，被她抓个正着。"},{"t":"n","text":"她打电话给你，说：「你猜那孩子在墙上画了什么。」"},{"t":"n","text":"你说不知道。她说：「一片雨。斜的。」"},{"t":"n","text":"她在电话那头笑，笑着笑着不说话了。"},{"t":"n","text":"过了一会儿，她说：「我小时候也这样。」"},{"t":"n","text":"你说，我知道。"},{"t":"n","text":"她的展，你一共做过七次。"},{"t":"n","text":"第一次在仓库，第二次在书店，第三次在一间废弃的邮局。"},{"t":"n","text":"第四次开始，有人来找她。第五次，有媒体来。第六次，票要提前预约。"},{"t":"n","text":"每一次布展，你们都要吵一次架。吵的都是很小的事：画挂多高，灯从哪个角度打。"},{"t":"n","text":"她说：「你不懂画。」"},{"t":"n","text":"你说：「我懂看画的人。」"},{"t":"n","text":"最后通常是各让一步。她把画降下来五公分，你把灯挪开一点。"},{"t":"n","text":"第七次，她让你写前言。你写了三百字，改了四遍。"},{"t":"n","text":"她看完，说：「你写得比我画得好。」"},{"t":"n","text":"你说，那是你画得好，我才写得出。"},{"t":"n","text":"她把那张纸折起来，放进展签盒里。"},{"t":"n","text":"画室有个五岁的小学员，已经会在画布上乱涂。她不拦，只在旁边铺一张报纸。"},{"t":"n","text":"有一次那孩子问她：「老师，你画这个有什么用？」"},{"t":"n","text":"她想了很久，说：「没用。但是好看。」"},{"t":"n","text":"那孩子「哦」了一声，接着涂。"},{"t":"n","text":"她在旁边笑，笑得很轻。"},{"t":"n","text":"你搬家那年，她来帮你挂画。"},{"t":"n","text":"新房子有一面很长的墙。她说：「这面好。光从左边来。」"},{"t":"n","text":"她量了尺寸，钉了两个钉子，让你退后看。"},{"t":"n","text":"你说歪了。她说：「没歪。是你的墙歪。」"},{"t":"n","text":"最后挂上去的是一张旧的速写，画的是地铁上的人。"},{"t":"n","text":"她站在下面看，说：「这张我自己都忘了。」"},{"t":"n","text":"你说，我一直留着。"},{"t":"n","text":"她转过头看你，看了两秒，说：「你这个人，真是。」"},{"t":"n","text":"她没说下去。你也没问。"},{"t":"n","text":"挂完画，你们坐在纸箱上吃外卖。她接了一个画室学员的电话，说：「老师在朋友家。」"},{"t":"n","text":"挂了电话，她说：「那孩子说要来看你。他说你的走廊像美术馆。」"},{"t":"n","text":"你说，随时来。给他留了一面矮墙。"}],"quality":{"high":["你们不常见面，但每次见面都像昨天刚见过。","她的事你都知道，你的事她也知道。中间隔着的那些年，不需要补。"],"mid":["她的展览你还会去。有时候忙，就错过。她会说：「没事，下次。」","下次总是有的。"],"low":["有一年她搬去了很远的城市。你们从一年见两次，变成只在朋友圈点赞。","那张肖像还挂在你家走廊。画里的那个人，一直很年轻。","有一年你在她的展上帮忙，站在门口发票。有人问你：「你是她什么人？」","你说，朋友。","那人说：「她画的人，好像都认识很久。」","你说，是。","那天收工很晚。她把卷帘门拉下来，说：「明天别来了，累。」","第二天你还是去了。"]},"id":"jiangwan_23","ending":"friend","endingName":"结局三 · 画外的朋友"}]}],"events":[{"id":"jw1","title":"速写本","triggerWeek":0,"bg":"artstudio_day","cast":[],"intro":[{"t":"n","text":"她的速写本掉在地上，摊开的那一页画着一只手，手里握着一支笔。"},{"t":"n","text":"再往前翻，是公交车上的人、食堂的窗口、一只睡在电动车座上的猫。"},{"t":"n","text":"最后一页是空的，纸边有点卷。"}],"opts":[{"label":"A","text":"一页一页翻完","hint":"看她的眼睛 · 好感 ↑","eff":{"aff":3.0,"happy":1.0},"reply":[{"t":"npc","name":"她说","text":"看可以。别评价。"}]},{"label":"B","text":"合上，放回原处","hint":"不动别人的东西","eff":{"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"她回来找了半天，发现在本子下面"}]},{"label":"C","text":"在最后一页画她","hint":"留一页给她 · 创造 ↑","eff":{"aff":4.0,"cre":1.0,"happy":2.0},"reply":[{"t":"n","text":"她看了很久，说：「你把我画胖了。」然后把那一页折了个角"}]}]},{"id":"jw2","title":"颜料涨价","triggerWeek":30,"bg":"artstudio_day","cast":[],"intro":[{"t":"n","text":"她站在货架前，手里拿着一管群青，看了很久价签。"},{"t":"n","text":"「又涨了。」她说，「上个月十四，这个月十七。」"},{"t":"n","text":"她把那管放回去，又拿起来，最后放进了购物篮。"}],"opts":[{"label":"A","text":"买一管送她","hint":"替她拎一点 · 好感 ↑","eff":{"aff":4.0,"fin":-2.0},"reply":[{"t":"n","text":"她收了，说「记账上」，你说不用记。她说：「那不行。」"}]},{"label":"B","text":"陪她再去别家看看","hint":"多走两家 · 心情 ↑","eff":{"aff":2.0,"happy":2.0},"reply":[{"t":"n","text":"走了三家，最后在巷子里那家便宜两块。她说：「值。」"}]},{"label":"C","text":"说「少画点」","hint":"说句实话 · 气氛 ↓","eff":{"aff":-3.0,"stress":1.0},"reply":[{"t":"n","text":"她把篮子放下了，说：「那我干什么。」"}]}]},{"id":"jw3","title":"家里的电话","triggerWeek":35,"bg":"artstudio_day","cast":[],"intro":[{"t":"n","text":"手机在画布旁边震。屏幕上是「妈」。"},{"t":"n","text":"她看了三秒，接起来，走到窗边。"},{"t":"n","text":"「嗯。」「在画。」「吃了。」「知道了。」"},{"t":"n","text":"挂了以后，她在窗边站了一会儿，回来接着画。"}],"opts":[{"label":"A","text":"陪她站一会儿","hint":"不说话 · 心情 ↑","eff":{"aff":4.0,"stress":1.0,"eq":1.0},"reply":[{"t":"npc","name":"她说","text":"我妈每次打完电话，我都要画一会儿才缓过来。"}]},{"label":"B","text":"帮她把话岔开","hint":"说点别的 · 心情 ↑","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说明天有雨。她说：「那正好，颜料干得慢。」"}]},{"label":"C","text":"不插手","hint":"让她自己待着","eff":{},"reply":[{"t":"n","text":"无变化。她画到很晚，走的时候跟你说「明天见」"}]}]},{"id":"jw4","title":"雨天的画室","triggerWeek":0,"bg":"artstudio_day","cast":[],"intro":[{"t":"n","text":"雨下得很大，画室的窗又漏了。她拿一个铁皮桶接水，滴答，滴答。"},{"t":"n","text":"「今天画不了油画。」她说，「太潮。」"},{"t":"n","text":"她把画布转到背面，在木框上画速写。"}],"opts":[{"label":"A","text":"留下来陪她","hint":"听雨 · 心情 ↑","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你们听了一个小时的雨。她说：「这个声音，比音乐好。」"}]},{"label":"B","text":"送伞就走","hint":"把伞留下 · 好感 ↑","eff":{"aff":2.0,"eq":1.0},"reply":[{"t":"n","text":"她接过伞，说：「你呢。」你说你跑得快"}]},{"label":"C","text":"忘了带伞","hint":"淋一次雨","eff":{"aff":-2.0,"happy":-1.0},"reply":[{"t":"n","text":"第二天你发烧，她来看你，带了一袋橘子，说：「笨。」"}]}]},{"id":"jw5","title":"第一次卖画","triggerWeek":50,"bg":"artstudio_night","cast":[],"intro":[{"t":"n","text":"第一笔钱到账，两千四。她把手机给你看，屏幕上是一个转账记录。"},{"t":"n","text":"「扣掉画布和颜料，赚八百。」她说，「还有我两个月的命。」"},{"t":"n","text":"她笑着说完，坐在地板上，抱着膝盖，没说话。"}],"opts":[{"label":"A","text":"替她高兴","hint":"先庆祝 · 心情 ↑","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你们去楼下吃了一碗面，加了两个蛋"}]},{"label":"B","text":"问她舍不舍得","hint":"问那句真的 · 好感 ↑","eff":{"aff":4.0,"happy":-1.0},"reply":[{"t":"n","text":"她想了很久，说：「舍不得。但是我得更舍不得房租。」"}]},{"label":"C","text":"让她自己决定怎么花","hint":"不替她做主","eff":{"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"她第二天买了一块新画布，剩下的存起来"}]}]},{"id":"jw6","title":"天台的门","triggerWeek":28,"bg":"rooftop_sunset","cast":[],"intro":[{"t":"n","text":"天台的门锁换过了，新的，挂着一把铜锁。"},{"t":"n","text":"她站在门前，伸手拉了一下，锁「哐」地响了一声。"},{"t":"n","text":"「行吧。」她说，「以后不能上来了。」"}],"opts":[{"label":"A","text":"去找后勤要钥匙","hint":"替她跑一趟 · 好感 ↑","eff":{"aff":4.0,"eq":1.0},"reply":[{"t":"n","text":"钥匙没要到，但管理员说「你们别在上面过夜就行」"}]},{"label":"B","text":"说「我们翻过去」","hint":"有点胡闹 · 心情 ↑","eff":{"aff":3.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"翻过去以后，风还是那个风。她笑了很久"}]},{"label":"C","text":"说「那就别上了」","hint":"算了 · 心情 ↓","eff":{"aff":-1.0,"happy":1.0},"reply":[{"t":"n","text":"她收回手，说：「也是。天台又不能当饭吃。」"}]}]},{"id":"jw7","title":"她给你画的像","triggerWeek":39,"bg":"artstudio_day","cast":[],"intro":[{"t":"n","text":"你在她的画架后面发现一张小画，三十乘四十，画的是你。"},{"t":"n","text":"画里的你在低头看手机，头发有点乱，嘴角是松的。"},{"t":"n","text":"右下角没有签名，只有一个很小的日期。"}],"opts":[{"label":"A","text":"问她能不能拿走","hint":"开口要 · 好感 ↑","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"npc","name":"她说","text":"拿吧。别挂客厅，挂走廊。"}]},{"label":"B","text":"装作没看见","hint":"装作不知道","eff":{"aff":1.0,"eq":1.0},"reply":[{"t":"n","text":"后来那张画不见了，你也没问"}]},{"label":"C","text":"说「画得不像」","hint":"嘴硬 · 气氛 ↑","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"npc","name":"她说","text":"哪儿不像。」你说：「我没这么好看。」她笑：「这倒是真的。"}]}]}],"endingNames":{"stay":"结局一 · 把时间画下来","miss":"结局二 · 有些颜色，一个人看也算数（爱过 / 错过）","friend":"结局三 · 画外的朋友"},"epilogue":{"title":"一面墙","bg":"artstudio_day","cast":["jiangwan"],"common":[{"t":"n","text":"她终于有了一面自己的墙。"},{"t":"n","text":"不大，二十来平，在城郊，一楼。墙是她自己刷的，刷了三遍，第三遍才均匀。"},{"t":"n","text":"门边挂着一个很小的相框，玻璃后面是一块巴掌大的墙皮。"},{"t":"n","text":"白涂料，边缘参差，露出底下的水泥。上面有一小片斜的蓝。"},{"t":"n","text":"相框下面贴着一张标签，手写的：「三楼，走廊尽头，画于八岁。」"},{"t":"n","text":"你站在门口看那块墙皮，看了很久。"},{"t":"n","text":"她走过来，把门推开。"},{"t":"c","id":"jiangwan","text":"别看了。进来。"},{"t":"n","text":"屋里有人。两个是她的学生，一个在画几何体，一个在画一只苹果。"},{"t":"n","text":"靠墙一排架子，颜料按色系排开，比画材店还整齐。"},{"t":"n","text":"架子上贴着一张纸：用完放回。下面一行小字：别挤我的白。"},{"t":"n","text":"她给你倒水，杯子还是买酸奶送的那种。"},{"t":"c","id":"jiangwan","text":"这个地方租了十年。房东答应了。"},{"t":"n","text":"十年。她说得很轻，像在报一个价。"},{"t":"n","text":"窗外的街上有人在修自行车，铁皮工具盒响了一下。"},{"t":"n","text":"她走到窗边，把窗推开一条缝。风进来，把架子上的一张画纸吹得翻了个角。"},{"t":"n","text":"她把纸压好，说：「这里风大。夏天好，冬天不行。」"},{"t":"n","text":"窗台上有几管用剩的颜料，按长短排着。最短的那管，是赭石。"}],"variants":{"stay":[{"t":"n","text":"墙是你们一起刷的。她刷高处，你刷低处，涂料滴在报纸上，干了以后一撕就掉。"},{"t":"n","text":"靠窗那面留给她，靠门那面留给你钉东西。"},{"t":"n","text":"她在那面墙的角落里画了一小片海，只有巴掌大。"},{"t":"n","text":"「占个位。」她说，「以后整面都要画。」"}],"miss":[{"t":"n","text":"这面墙在她北京的第二次个展上，被整个复刻了一遍。"},{"t":"n","text":"展厅里搭了一堵假墙，墙上只有那块墙皮和一张标签。"},{"t":"n","text":"来看的人不明白那是什么，站在前面拍照。"},{"t":"n","text":"你站在人群里，看她隔着几个人介绍这面墙的来历。"},{"t":"n","text":"她说得很平静，像在说一个别人的故事。"}],"friend":[{"t":"n","text":"你帮她把画挂上墙。水平仪是你带的，钉子是她钉的。"},{"t":"n","text":"画室的小学员蹲在地上，用剩下的颜料在墙根画了一排小人。"},{"t":"n","text":"她看了一眼，没有阻止，只说：「画低一点。上面我要用。」"},{"t":"n","text":"学员问：「老师，这面墙是你的吗。」"},{"t":"n","text":"她说：「是。」"},{"t":"n","text":"停了一下，她又说：「也是你们的。」"}]},"outro":[{"t":"n","text":"她带你去看她的账本。还是那种纸，还是那些栏目：房租、材料、代课、卖画。"},{"t":"n","text":"这次最后不是负数，剩了一点。"},{"t":"n","text":"「够买两台暖气。」她说，「去年冬天手冻裂了，画不了细的。」"},{"t":"n","text":"你问她，那块墙皮是什么时候装进相框的。"},{"t":"n","text":"她说是去年。搬了七次家，那块东西一直用报纸包着，放在装颜料的箱子里。"},{"t":"c","id":"jiangwan","text":"有一次差点扔了。以为是块砖。"},{"t":"n","text":"她说这话的时候在笑，笑到一半，声音低下去。"},{"t":"c","id":"jiangwan","text":"我怕弄丢。所以先装起来。"},{"t":"n","text":"她站在墙前面，手里拿着一支笔，笔尖悬着。"},{"t":"n","text":"窗外的光斜进来，照在墙上，一个下午慢慢往西挪。"},{"t":"n","text":"你想起很多年前，少年宫三楼的走廊。她蹲在墙根，用一支很短的赭石蜡笔，画下一片斜的雨。"},{"t":"n","text":"后来她把那块墙割下来，用报纸包好，带走。"},{"t":"n","text":"那时候她说：「以后我要有一间自己的墙。整面墙都是我的。」"},{"t":"n","text":"现在她有了。"},{"t":"c","id":"jiangwan","text":"你说，这个蓝是不是太亮了。"},{"t":"n","text":"你看了很久。今天的蓝，跟她画过的每一片天都不太一样。"},{"t":"n","text":"你说，刚好。"},{"t":"n","text":"她笑了一下，落笔。"},{"t":"n","text":"笔在墙上走，很轻。光跟着她的手，一点一点移过去。"}]}};
